-- HotsBB Talents — import meta talent builds per raid boss / dungeon for your current spec.
--
-- Data.lua (generated by scripts/export-meta-builds.js) ships three globals:
--   HotsBBTalentsMeta    — schema version, generation time, season label, raid difficulty
--   HotsBBTalentsRoster  — the season's ordered raid bosses and dungeons, with WCL and
--                          Blizzard Encounter Journal IDs
--   HotsBBTalentsData    — [specID][encounterName] = { sampleSize, fetchedAt, variants }
-- Core.lua never hardcodes season content: the roster travels with the data it describes
-- (an earlier version did hardcode it, and silently showed "No data yet" for a whole
-- season after the content rolled over).
--
-- Import decodes a build client-side into ImportLoadoutEntryInfo rows (a port of
-- Blizzard's ClassTalentImportExportMixin plus WCL-telemetry entry resolution), creates a
-- named loadout through C_ClassTalents.ImportLoadout, then switches to it. Copy / Link
-- remain as zero-dependency fallbacks that hand the raw Blizzard string to the player.

local ADDON_NAME = ...

local HBT = {}
_G.HotsBBTalents = HBT

local ADDON_TITLE = "HotsBB Talents"
local CHAT_PREFIX = "|cff7ec8ffHotsBB Talents:|r "
local LOADOUT_PREFIX = "HBT "
local MAX_LOADOUT_NAME = 28
local utf8len = strlenutf8 or string.len
-- Character-based substring (WoW has no string.utf8sub); cuts on codepoint boundaries.
local function utf8sub(s, i, j)
  local chars = {}
  for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do chars[#chars + 1] = ch end
  j = j or #chars
  if j > #chars then j = #chars end
  return table.concat(chars, "", i, j)
end

-- ── Saved variables ──────────────────────────────────────────────────────────

local DEFAULTS = {
  autoApply = true,        -- after Import, switch to the new loadout and apply it
  replaceExisting = true,  -- an older HBT loadout with the same name is replaced, not duplicated
  showTalentButton = true, -- shortcut on Blizzard's Talents screen
  showJournalButton = true,-- shortcut in the Encounter Journal boss page
  chatMessages = true,     -- echo import results to chat (the on-screen banner always shows)
  scale = 1,
  lastTab = "raid",
  minimap = { hide = false, angle = 220 },
  panel = { width = 500, height = 580 },
}

local db, charDB

local function MergeDefaults(dest, src)
  for k, v in pairs(src) do
    if type(v) == "table" then
      if type(dest[k]) ~= "table" then dest[k] = {} end
      MergeDefaults(dest[k], v)
    elseif dest[k] == nil then
      dest[k] = v
    end
  end
end

local function InitSavedVariables()
  HotsBBTalentsDB = type(HotsBBTalentsDB) == "table" and HotsBBTalentsDB or {}
  HotsBBTalentsCharDB = type(HotsBBTalentsCharDB) == "table" and HotsBBTalentsCharDB or {}
  db = HotsBBTalentsDB
  charDB = HotsBBTalentsCharDB
  MergeDefaults(db, DEFAULTS)
  if type(charDB.pills) ~= "table" then charDB.pills = {} end
end

-- ── Messaging ────────────────────────────────────────────────────────────────
-- Chat prints alone are easy to miss in a busy chat window (an early version's
-- "GetActiveConfigID returned nil" went unnoticed for that reason), so every result is
-- paired with an on-screen banner. Chat echo is a setting; the banner is not.

local function Announce(msg, r, g, b)
  if not db or db.chatMessages then print(CHAT_PREFIX .. msg) end
  if UIErrorsFrame then
    local plain = msg:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", ""):gsub("|T.-|t", ""):gsub("|A.-|a", "")
    UIErrorsFrame:AddMessage(ADDON_TITLE .. ": " .. plain, r or 1, g or 1, b or 1)
  end
end
local function Fail(msg) Announce(msg, 1.0, 0.35, 0.35) end
local function Succeed(msg) Announce(msg, 0.35, 1.0, 0.35) end
local function Note(msg) Announce(msg, 1.0, 0.85, 0.4) end

local function GetCurrentSpecID()
  local specIndex = GetSpecialization and GetSpecialization()
  if not specIndex then return nil end
  return (GetSpecializationInfo(specIndex))
end

-- ── Data access ──────────────────────────────────────────────────────────────

local META = HotsBBTalentsMeta
local ROSTER = HotsBBTalentsRoster
local DATA = HotsBBTalentsData or {}
local SCHEMA_OK = (type(META) == "table" and META.schemaVersion == 2) or META == nil

-- Fallback for a Data.lua older than this Core.lua (no roster block): every encounter
-- name present in the data, in alphabetical order, under the Raid tab. Degrades the UI
-- rather than erroring; the subtitle tells the player to update.
if type(ROSTER) ~= "table" then
  local names, seen = {}, {}
  for _, encounters in pairs(DATA) do
    for name in pairs(encounters) do
      if not seen[name] then seen[name] = true; names[#names + 1] = name end
    end
  end
  table.sort(names)
  ROSTER = { raid = {}, dungeons = {}, legacy = true }
  for _, name in ipairs(names) do ROSTER.raid[#ROSTER.raid + 1] = { name = name } end
end
-- A journal ID of 0 (WCL's "unknown") is the same as no journal ID.
for _, entry in ipairs(ROSTER.raid or {}) do
  if not entry.journalId or entry.journalId == 0 then entry.journalId = nil end
end
for _, entry in ipairs(ROSTER.dungeons or {}) do
  if not entry.journalInstanceId or entry.journalInstanceId == 0 then entry.journalInstanceId = nil end
end

-- Compact per-variant strings (see export script) are parsed once on first use and
-- cached on the variant itself. Legacy table-shaped fields are accepted too, so this
-- Core.lua runs against a Data.lua of either schema.
local function ParseFreq(variant)
  if variant._freq then return variant._freq end
  local out = {}
  if type(variant.frequencyPct) == "table" then
    out = variant.frequencyPct
  elseif type(variant.freq) == "string" then
    for nodeID, pct in variant.freq:gmatch("(%d+):(%d+)") do
      out[tonumber(nodeID)] = tonumber(pct)
    end
  end
  variant._freq = out
  return out
end

local function ParseEntries(variant)
  if variant._entries ~= nil then return variant._entries or nil end
  local out
  if type(variant.wclEntries) == "table" then
    out = variant.wclEntries
  elseif type(variant.entries) == "string" then
    out = {}
    for row in variant.entries:gmatch("[^,]+") do
      local nodeID, entryID, purchased, granted = row:match("^(%d+):(%d+):(%d+):?(%d*)$")
      if nodeID then
        out[#out + 1] = {
          nodeID = tonumber(nodeID),
          selectionEntryID = tonumber(entryID),
          ranksPurchased = tonumber(purchased),
          ranksGranted = tonumber(granted) or 0,
        }
      end
    end
    if #out == 0 then out = nil end
  end
  variant._entries = out or false
  return out
end

local function GetSpecData(specID)
  return specID and DATA[specID] or nil
end

local function RosterFor(tabKey)
  return tabKey == "raid" and ROSTER.raid or ROSTER.dungeons
end

-- Days since the data was generated, or nil when the data file predates the meta block.
local function DataAgeDays()
  if not META or not META.generatedAt then return nil end
  local now = GetServerTime and GetServerTime() or time()
  return math.max(0, math.floor((now - META.generatedAt) / 86400))
end

-- ── Loadout string decoder ───────────────────────────────────────────────────
-- Faithful port of Blizzard's Blizzard_ClassTalentImportExport.lua
-- (ClassTalentImportExportMixin). Field order and bit widths match that source.

local BIT_WIDTH_HEADER_VERSION = 8
local BIT_WIDTH_SPEC_ID = 16
local BIT_WIDTH_RANKS_PURCHASED = 6
local LOADOUT_HEADER_BITS = BIT_WIDTH_HEADER_VERSION + BIT_WIDTH_SPEC_ID + 16 * 8

local function HashEquals(a, b)
  if #a ~= #b then return false end
  for i = 1, #a do
    if a[i] ~= b[i] then return false end
  end
  return true
end

local function IsHashEmpty(hash)
  for _, v in ipairs(hash) do
    if v ~= 0 then return false end
  end
  return true
end

local function ReadLoadoutHeader(importStream)
  if importStream.GetNumberOfBits and importStream:GetNumberOfBits() < LOADOUT_HEADER_BITS then
    error("string too short")
  end
  local serializationVersion = importStream:ExtractValue(BIT_WIDTH_HEADER_VERSION)
  local specID = importStream:ExtractValue(BIT_WIDTH_SPEC_ID)
  local treeHash = {}
  for i = 1, 16 do
    treeHash[i] = importStream:ExtractValue(8)
  end
  return serializationVersion, specID, treeHash
end

local function ReadLoadoutContent(importStream, treeID)
  local results = {}
  local treeNodes = C_Traits.GetTreeNodes(treeID)
  for i = 1, #treeNodes do
    local isNodeSelected = importStream:ExtractValue(1) == 1
    local isNodePurchased = false
    local isPartiallyRanked = false
    local partialRanksPurchased = 0
    local isChoiceNode = false
    local choiceNodeSelection = 0

    if isNodeSelected then
      isNodePurchased = importStream:ExtractValue(1) == 1
      if isNodePurchased then
        isPartiallyRanked = importStream:ExtractValue(1) == 1
        if isPartiallyRanked then
          partialRanksPurchased = importStream:ExtractValue(BIT_WIDTH_RANKS_PURCHASED)
        end
        isChoiceNode = importStream:ExtractValue(1) == 1
        if isChoiceNode then
          choiceNodeSelection = importStream:ExtractValue(2)
        end
      end
    end

    results[i] = {
      isNodeSelected = isNodeSelected,
      isNodeGranted = isNodeSelected and not isNodePurchased,
      isPartiallyRanked = isPartiallyRanked,
      partialRanksPurchased = partialRanksPurchased,
      isChoiceNode = isChoiceNode,
      choiceNodeSelection = choiceNodeSelection + 1,
    }
  end
  return results
end

local function CreateEntryFromSingleNode(results, treeNodeInfo, indexInfo)
  if not treeNodeInfo or not indexInfo or not indexInfo.isNodeSelected then return end

  local result = { nodeID = treeNodeInfo.ID }
  result.ranksGranted = indexInfo.isNodeGranted and 1 or 0
  if indexInfo.isNodeSelected and not indexInfo.isNodeGranted then
    result.ranksPurchased = indexInfo.isPartiallyRanked and indexInfo.partialRanksPurchased or treeNodeInfo.maxRanks
  else
    result.ranksPurchased = 0
  end

  result.selectionEntryID = nil
  if indexInfo.isChoiceNode and indexInfo.choiceNodeSelection then
    result.selectionEntryID = treeNodeInfo.entryIDs[indexInfo.choiceNodeSelection]
  elseif treeNodeInfo.activeEntry then
    result.selectionEntryID = treeNodeInfo.activeEntry.entryID
  end
  if not result.selectionEntryID then
    result.selectionEntryID = treeNodeInfo.entryIDs[1]
  end

  if result.selectionEntryID ~= nil then
    table.insert(results, result)
  end
end

-- Tiered nodes (Priest's Benediction, Warrior's Tigereye Brew, …) store each rank as a
-- separate TraitNodeEntry. ImportLoadout needs one row per sub-entry invested in, in the
-- client's canonical entryIDs order, capped at each entry's real maxRanks — otherwise it
-- silently drops the ranks it can't place.
local function BuildTieredNodeEntries(results, configID, treeNodeInfo, totalRanksPurchased, isNodeGranted)
  local remainingRanks = totalRanksPurchased
  for index, entryID in ipairs(treeNodeInfo.entryIDs) do
    local entryInfo = C_Traits.GetEntryInfo(configID, entryID)
    if entryInfo then
      local ranksForThisEntry = math.min(remainingRanks, entryInfo.maxRanks)
      local isGranted = isNodeGranted and (index == 1)
      if ranksForThisEntry > 0 or isGranted then
        table.insert(results, {
          nodeID = treeNodeInfo.ID,
          ranksGranted = isGranted and 1 or 0,
          ranksPurchased = ranksForThisEntry,
          selectionEntryID = entryID,
        })
      end
      remainingRanks = remainingRanks - ranksForThisEntry
    end
  end
end

local function CreateEntryFromTieredNode(results, configID, treeNodeInfo, indexInfo)
  if not treeNodeInfo or not indexInfo or not indexInfo.isNodeSelected then return end
  local totalRanksPurchased = 0
  if not indexInfo.isNodeGranted then
    totalRanksPurchased = indexInfo.isPartiallyRanked and indexInfo.partialRanksPurchased or treeNodeInfo.maxRanks
  end
  BuildTieredNodeEntries(results, configID, treeNodeInfo, totalRanksPurchased, indexInfo.isNodeGranted)
end

local function ConvertToImportLoadoutEntryInfo(configID, treeID, loadoutContent)
  local results = {}
  local treeNodes = C_Traits.GetTreeNodes(treeID)
  for index, treeNodeID in ipairs(treeNodes) do
    local indexInfo = loadoutContent[index]
    local treeNodeInfo = C_Traits.GetNodeInfo(configID, treeNodeID)
    if treeNodeInfo then
      if treeNodeInfo.type == Enum.TraitNodeType.Tiered then
        CreateEntryFromTieredNode(results, configID, treeNodeInfo, indexInfo)
      else
        CreateEntryFromSingleNode(results, treeNodeInfo, indexInfo)
      end
    end
  end
  return results
end

-- Decodes a Blizzard loadout string into ImportLoadoutEntryInfo[]. Returns entries, nil
-- on success or nil, errorMessage on failure. Error text uses Blizzard's own localized
-- globals where they exist. `skipSpecCheck` lets callers decode strings generated for
-- saved loadouts of the same spec without re-asserting the spec.
local function DecodeLoadoutString(importString, configID, treeID, skipSpecCheck)
  if not (ExportUtil and ExportUtil.MakeImportDataStream) then
    return nil, "ExportUtil.MakeImportDataStream not found on this client"
  end
  local cleaned = importString:gsub("^%s*talents=", ""):gsub("%s+", "")
  local importStream = ExportUtil.MakeImportDataStream(cleaned)

  local okHeader, serializationVersion, specID, treeHash = pcall(ReadLoadoutHeader, importStream)
  if not okHeader then
    return nil, LOADOUT_ERROR_BAD_STRING or "Not a valid talent string"
  end

  if C_Traits.GetLoadoutSerializationVersion and serializationVersion ~= C_Traits.GetLoadoutSerializationVersion() then
    return nil, LOADOUT_ERROR_SERIALIZATION_VERSION_MISMATCH or "Talent string is from a different game version"
  end
  if not skipSpecCheck then
    local currentSpecID = GetCurrentSpecID()
    if currentSpecID and specID ~= currentSpecID then
      return nil, LOADOUT_ERROR_WRONG_SPEC or "This build is for a different specialization"
    end
  end
  if not IsHashEmpty(treeHash) and C_Traits.GetTreeHash then
    local currentHash = C_Traits.GetTreeHash(treeID)
    if currentHash and not HashEquals(treeHash, currentHash) then
      return nil, LOADOUT_ERROR_TREE_CHANGED or "The talent tree has changed since this build was recorded"
    end
  end

  local okContent, content = pcall(ReadLoadoutContent, importStream, treeID)
  if not okContent then
    return nil, LOADOUT_ERROR_BAD_STRING or "Failed to read talent string"
  end

  local okEntries, entries = pcall(ConvertToImportLoadoutEntryInfo, configID, treeID, content)
  if not okEntries then
    return nil, "Failed to build entries: " .. tostring(entries)
  end
  if #entries == 0 then
    return nil, "Decoded loadout has no talents selected"
  end
  return entries, nil
end

-- WCL telemetry rows are a permanent historical record: a row's selectionEntryID is
-- whatever was valid when the fight happened, and Blizzard hotfixes regenerate entry IDs
-- without changing the tree's shape. ImportLoadout silently drops any row it can't
-- place, so each row is checked against this client's live entryIDs: a single-option
-- node is corrected to its one real option, a multi-option node that no longer matches
-- is dropped (never guessed), and Tiered nodes are rebuilt from the total rank count.
-- Returns resolvedEntries, droppedCount — callers must surface droppedCount, because a
-- green "imported" banner over a half-applied build is worse than an honest warning.
local function ResolveWclEntries(configID, rawEntries)
  local order, byNode = {}, {}
  for _, e in ipairs(rawEntries) do
    if not byNode[e.nodeID] then
      byNode[e.nodeID] = {}
      table.insert(order, e.nodeID)
    end
    table.insert(byNode[e.nodeID], e)
  end

  local results, dropped = {}, 0
  for _, nodeID in ipairs(order) do
    local rows = byNode[nodeID]
    local treeNodeInfo = C_Traits.GetNodeInfo(configID, nodeID)
    if not (treeNodeInfo and treeNodeInfo.entryIDs and #treeNodeInfo.entryIDs > 0) then
      dropped = dropped + #rows
    elseif treeNodeInfo.type == Enum.TraitNodeType.Tiered then
      local totalRanksPurchased, isNodeGranted = 0, false
      for _, row in ipairs(rows) do
        totalRanksPurchased = totalRanksPurchased + (row.ranksPurchased or 0)
        if (row.ranksGranted or 0) > 0 then isNodeGranted = true end
      end
      BuildTieredNodeEntries(results, configID, treeNodeInfo, totalRanksPurchased, isNodeGranted)
    else
      for _, row in ipairs(rows) do
        local resolvedRow = row
        local isValid = false
        for _, validID in ipairs(treeNodeInfo.entryIDs) do
          if validID == row.selectionEntryID then
            isValid = true
            break
          end
        end
        if not isValid then
          if #treeNodeInfo.entryIDs == 1 then
            resolvedRow = {
              nodeID = row.nodeID,
              ranksGranted = row.ranksGranted or 0,
              ranksPurchased = row.ranksPurchased or 0,
              selectionEntryID = treeNodeInfo.entryIDs[1],
            }
          else
            resolvedRow = nil
            dropped = dropped + 1
          end
        end
        if resolvedRow then
          table.insert(results, resolvedRow)
        end
      end
    end
  end
  return results, dropped
end

-- C_Traits.GetTreeNodes order is a valid dependency order (prerequisites precede their
-- children); ImportLoadout processes entries sequentially, so arbitrary-order WCL rows
-- could drop a capstone whose prerequisite hadn't been placed yet. Stable sort.
local function SortEntriesByTreeOrder(entries, treeID)
  local treeNodes = C_Traits.GetTreeNodes(treeID)
  local orderIndex = {}
  for i, nodeID in ipairs(treeNodes) do orderIndex[nodeID] = i end
  local indexed = {}
  for i, entry in ipairs(entries) do
    indexed[i] = { entry = entry, order = orderIndex[entry.nodeID] or math.huge, orig = i }
  end
  table.sort(indexed, function(a, b)
    if a.order ~= b.order then return a.order < b.order end
    return a.orig < b.orig
  end)
  local sorted = {}
  for i, item in ipairs(indexed) do sorted[i] = item.entry end
  return sorted
end

-- ── Talent config helpers ────────────────────────────────────────────────────

-- The active config and its tree. Never force-opens the Talents frame: showing/hiding
-- PlayerSpellsFrame from addon code taints action-bar state (confirmed by other addon
-- authors), so when the config isn't resolvable yet the player is asked to open it once.
local function GetActiveConfig()
  if not (C_ClassTalents and C_ClassTalents.GetActiveConfigID and C_Traits and C_Traits.GetConfigInfo) then
    return nil
  end
  -- No LoadAddOn("Blizzard_PlayerSpells") here either: loading a Blizzard LoD addon from
  -- insecure code taints everything it creates. GetActiveConfigID doesn't need it.
  local configID = C_ClassTalents.GetActiveConfigID()
  if not configID then return nil end
  local configInfo = C_Traits.GetConfigInfo(configID)
  local treeID = configInfo and configInfo.treeIDs and configInfo.treeIDs[1]
  if not treeID then return nil end
  return configID, treeID
end

-- Entries for a variant against the live client: WCL rows resolved and tree-sorted when
-- present, else the Blizzard string decoded. Returns entries, dropped, err.
local function EntriesForVariant(variant, configID, treeID)
  local raw = ParseEntries(variant)
  if raw and C_Traits.GetEntryInfo then
    local entries, dropped = ResolveWclEntries(configID, raw)
    if #entries > 0 then
      return SortEntriesByTreeOrder(entries, treeID), dropped, nil
    end
  end
  if variant.importString then
    local entries, err = DecodeLoadoutString(variant.importString, configID, treeID)
    if entries then return entries, 0, nil end
    return nil, 0, err
  end
  return nil, 0, "no import data for this build"
end

-- Hero-tree selection nodes are excluded from every state map: a Blizzard string encodes
-- the hero pick as a purchased choice on that node while a saved config may not, and the
-- hero tree is implied by which hero nodes are purchased anyway. Both state builders must
-- agree on this or every diff carries a phantom entry.
local subTreeNodeCache = {}
local function IsSubTreeSelectionNode(configID, nodeID)
  local cached = subTreeNodeCache[nodeID]
  if cached ~= nil then return cached end
  local info = C_Traits.GetNodeInfo(configID, nodeID)
  local isSel = info ~= nil and info.type == Enum.TraitNodeType.SubTreeSelection
  subTreeNodeCache[nodeID] = isSel
  return isSel
end

-- ── Loadout string encoder ───────────────────────────────────────────────────
-- Inverse of the decoder above (mirrors ClassTalentImportExportMixin:WriteLoadoutHeader/
-- WriteLoadoutContent) so a build that arrived as WCL rows only still gets a Blizzard
-- import string for Copy / Link. Nodes are written in GetTreeNodes order; the hero-tree
-- selection node is synthesized from the variant's hero tree when the rows lack it (WCL
-- telemetry records the hero talents themselves, not the selector).
local function EncodeEntries(entries, configID, treeID, heroTreeId)
  if not (ExportUtil and ExportUtil.MakeExportDataStream and C_Traits.GetTreeNodes) then return nil end
  local specID = GetCurrentSpecID()
  if not specID then return nil end

  local byNode = {}
  for _, e in ipairs(entries) do
    local s = byNode[e.nodeID]
    if not s then
      s = { purchased = 0, granted = 0, entry = e.selectionEntryID }
      byNode[e.nodeID] = s
    end
    s.purchased = s.purchased + (e.ranksPurchased or 0)
    s.granted = s.granted + (e.ranksGranted or 0)
  end

  -- Hero tree: explicit on the variant, else inferred from any hero node in the rows.
  local heroID = heroTreeId
  if not heroID then
    for nodeID in pairs(byNode) do
      local info = C_Traits.GetNodeInfo(configID, nodeID)
      if info and info.subTreeID and info.subTreeID > 0 then heroID = info.subTreeID; break end
    end
  end

  local stream = ExportUtil.MakeExportDataStream()
  stream:AddValue(BIT_WIDTH_HEADER_VERSION, (C_Traits.GetLoadoutSerializationVersion and C_Traits.GetLoadoutSerializationVersion()) or 2)
  stream:AddValue(BIT_WIDTH_SPEC_ID, specID)
  local hash = C_Traits.GetTreeHash and C_Traits.GetTreeHash(treeID)
  for i = 1, 16 do stream:AddValue(8, (type(hash) == "table" and hash[i]) or 0) end

  local T = Enum.TraitNodeType
  for _, nodeID in ipairs(C_Traits.GetTreeNodes(treeID)) do
    local info = C_Traits.GetNodeInfo(configID, nodeID)
    local s = byNode[nodeID]
    if info and info.type == T.SubTreeSelection then
      local idx
      if heroID and info.entryIDs then
        for i, entryID in ipairs(info.entryIDs) do
          local ei = C_Traits.GetEntryInfo(configID, entryID)
          if ei and ei.subTreeID == heroID then idx = i; break end
        end
      end
      if idx then
        stream:AddValue(1, 1)        -- selected
        stream:AddValue(1, 1)        -- purchased
        stream:AddValue(1, 0)        -- not partially ranked
        stream:AddValue(1, 1)        -- choice node
        stream:AddValue(2, idx - 1)
      else
        stream:AddValue(1, 0)
      end
    elseif info and s and (s.purchased > 0 or s.granted > 0) then
      stream:AddValue(1, 1)
      if s.purchased > 0 then
        stream:AddValue(1, 1)
        local maxRanks = info.maxRanks or 1
        local partial = s.purchased < maxRanks
        stream:AddValue(1, partial and 1 or 0)
        if partial then stream:AddValue(BIT_WIDTH_RANKS_PURCHASED, s.purchased) end
        local isChoice = info.type == T.Selection
        stream:AddValue(1, isChoice and 1 or 0)
        if isChoice then
          local idx = 1
          for i, entryID in ipairs(info.entryIDs or {}) do
            if entryID == s.entry then idx = i; break end
          end
          stream:AddValue(2, idx - 1)
        end
      else
        stream:AddValue(1, 0) -- granted only
      end
    else
      stream:AddValue(1, 0)
    end
  end
  return stream:GetExportString()
end

-- Purchased-rank map of an entries array: nodeID -> { ranks, entry }. Only purchased
-- ranks count (granted ranks are free and identical in every build of the spec). Tiered
-- nodes contribute several rows; their total rank is compared, not the entry.
local function StateFromEntries(entries, configID)
  local state = {}
  for _, e in ipairs(entries) do
    local purchased = e.ranksPurchased or 0
    if purchased > 0 and not (configID and IsSubTreeSelectionNode(configID, e.nodeID)) then
      local s = state[e.nodeID]
      if s then
        s.ranks = s.ranks + purchased
        s.entry = nil -- multiple rows => tiered, entry comparison is meaningless
      else
        state[e.nodeID] = { ranks = purchased, entry = e.selectionEntryID }
      end
    end
  end
  return state
end

-- Purchased-rank map of a saved config straight from C_Traits (works for the active
-- config and for any saved loadout of this spec). Hero-tree selection nodes are skipped:
-- the hero tree is already implied by which hero nodes are purchased.
local function StateFromConfig(configID, treeID)
  local state = {}
  local nodes = C_Traits.GetTreeNodes(treeID)
  for _, nodeID in ipairs(nodes) do
    local info = C_Traits.GetNodeInfo(configID, nodeID)
    if info and (info.ranksPurchased or 0) > 0 and info.type ~= Enum.TraitNodeType.SubTreeSelection then
      -- Tiered nodes: compare total ranks only; which sub-entry is "active" is an
      -- implementation detail that differs between a saved config and WCL rows.
      local tiered = info.type == Enum.TraitNodeType.Tiered
      state[nodeID] = { ranks = info.ranksPurchased, entry = (not tiered) and info.activeEntry and info.activeEntry.entryID or nil }
    end
  end
  return state
end

-- Diff two states. Returns { adds = {nodeID,...}, removes = {...}, changes = {...}, total }.
local function DiffStates(current, target)
  local diff = { adds = {}, removes = {}, changes = {} }
  for nodeID, t in pairs(target) do
    local c = current[nodeID]
    if not c then
      diff.adds[#diff.adds + 1] = nodeID
    elseif c.ranks ~= t.ranks or (t.entry and c.entry and t.entry ~= c.entry) then
      diff.changes[#diff.changes + 1] = nodeID
    end
  end
  for nodeID in pairs(current) do
    if not target[nodeID] then diff.removes[#diff.removes + 1] = nodeID end
  end
  diff.total = #diff.adds + #diff.removes + #diff.changes
  return diff
end

-- Human name for a node's entry (or its active/first entry) via definition -> spell.
local function TalentName(configID, nodeID, entryID)
  local info = C_Traits.GetNodeInfo(configID, nodeID)
  if not info then return "Talent #" .. tostring(nodeID) end
  entryID = entryID or (info.activeEntry and info.activeEntry.entryID) or (info.entryIDs and info.entryIDs[1])
  if not entryID then return "Talent #" .. tostring(nodeID) end
  local entry = C_Traits.GetEntryInfo(configID, entryID)
  local def = entry and entry.definitionID and C_Traits.GetDefinitionInfo(entry.definitionID)
  if def then
    if def.overrideName and def.overrideName ~= "" then return def.overrideName end
    if def.spellID then
      local name = C_Spell and C_Spell.GetSpellName and C_Spell.GetSpellName(def.spellID)
      if not name and GetSpellInfo then name = GetSpellInfo(def.spellID) end
      if name then return name end
    end
  end
  return "Talent #" .. tostring(nodeID)
end

-- Current-state cache: rebuilt lazily, invalidated on trait events (see event frame).
local currentStateCache = { configID = nil, state = nil }
function HBT.InvalidateCurrentState() currentStateCache.state = nil end
local function GetCurrentState(configID, treeID)
  if currentStateCache.state and currentStateCache.configID == configID then
    return currentStateCache.state
  end
  local ok, state = pcall(StateFromConfig, configID, treeID)
  if not ok then return nil end
  currentStateCache.configID, currentStateCache.state = configID, state
  return state
end

-- Diff of the player's active talents vs a variant. Cached per variant until the
-- current-state cache is invalidated. Returns diff, entries, dropped (or nil when the
-- config isn't available yet).
local function DiffVariant(variant)
  local configID, treeID = GetActiveConfig()
  if not configID then return nil end
  local current = GetCurrentState(configID, treeID)
  if not current then return nil end
  if variant._diff and variant._diffState == current then return variant._diff, variant._diffEntries, variant._diffDropped end
  local entries, dropped = EntriesForVariant(variant, configID, treeID)
  if not entries then return nil end
  local diff = DiffStates(current, StateFromEntries(entries, configID))
  variant._diff, variant._diffState, variant._diffEntries, variant._diffDropped = diff, current, entries, dropped
  return diff, entries, dropped
end

-- The Blizzard import string for a variant: the one shipped with the data when present,
-- otherwise encoded from the resolved entries (cached per active config).
local function StringForVariant(variant)
  if variant.importString then return variant.importString end
  local configID, treeID = GetActiveConfig()
  if not configID then return nil end
  if variant._encoded ~= nil and variant._encodedFor == configID then return variant._encoded or nil end
  local entries = EntriesForVariant(variant, configID, treeID)
  local ok, str = false, nil
  if entries then ok, str = pcall(EncodeEntries, entries, configID, treeID, variant.heroTreeId) end
  variant._encoded = (ok and type(str) == "string" and str ~= "") and str or false
  variant._encodedFor = configID
  return variant._encoded or nil
end
HBT.StringForVariant = StringForVariant

-- ── Import & apply ───────────────────────────────────────────────────────────
-- A small state machine driven by trait events, so the whole flow is one click:
--   preflight → (reuse an identical saved loadout) → (delete the old HBT loadout of the
--   same name) → ImportLoadout → TRAIT_CONFIG_CREATED → LoadConfig(autoApply) → done.

local importState = nil -- { token, name, specID, ... }
local importEvents = CreateFrame("Frame")

local function StripMarkup(s)
  s = s:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", ""):gsub("|T.-|t", ""):gsub("|A.-|a", "")
  return strtrim and strtrim(s) or s
end

-- "HBT <boss> <hero>", shortened from the boss name first so two hero-tree variants of a
-- long boss name never collapse into the same loadout name (replaceExisting would then
-- delete one hero's loadout while importing the other's).
local function LoadoutNameFor(bossName, variant)
  local hero = (variant.heroTreeName and variant.heroTreeName ~= "Overall") and StripMarkup(variant.heroTreeName) or nil
  local suffix = hero and (" " .. hero) or ""
  local boss = StripMarkup(bossName)
  local budget = MAX_LOADOUT_NAME - utf8len(LOADOUT_PREFIX) - utf8len(suffix)
  if budget < 6 then
    -- Hero name itself is long: abbreviate it instead.
    suffix = " " .. utf8sub(hero, 1, 8)
    budget = MAX_LOADOUT_NAME - utf8len(LOADOUT_PREFIX) - utf8len(suffix)
  end
  if utf8len(boss) > budget then
    boss = utf8sub(boss, 1, math.max(1, budget - 1)) .. "…"
  end
  return LOADOUT_PREFIX .. boss .. suffix
end

local function SavedConfigsForSpec(specID)
  local ids = C_ClassTalents.GetConfigIDsBySpecID and C_ClassTalents.GetConfigIDsBySpecID(specID) or {}
  local out = {}
  for _, id in ipairs(ids) do
    local info = C_Traits.GetConfigInfo(id)
    if info then out[#out + 1] = { ID = id, name = info.name or "" } end
  end
  return out
end

local function FinishImport(success, msg)
  importEvents:UnregisterAllEvents()
  importState = nil
  if success then Succeed(msg) else Fail(msg) end
  HBT.InvalidateCurrentState()
  if HBT.RefreshIfShown then HBT.RefreshIfShown() end
end

-- Timeouts are bound to the stage they were armed for: a "creating" timeout must not
-- fire after the flow has already moved on to "loading".
local function ImportTimeout(token, stage, seconds, msg)
  C_Timer.After(seconds, function()
    if importState and importState.token == token and importState.stage == stage then FinishImport(false, msg) end
  end)
end

-- Step 3: switch to (and, with autoApply, commit) a saved loadout by ID.
local function SwitchToLoadout(configID, label)
  local specID = importState.specID
  if C_ClassTalents.UpdateLastSelectedSavedConfigID then
    pcall(C_ClassTalents.UpdateLastSelectedSavedConfigID, specID, configID)
  end
  if not db.autoApply then
    return FinishImport(true, "Saved \"" .. label .. "\". Select it from the loadout dropdown in your Talents panel to apply it.")
  end
  if InCombatLockdown() then
    return FinishImport(true, "Saved \"" .. label .. "\" — can't apply it in combat. Pick it from the loadout dropdown once you're out.")
  end
  local ok, result = pcall(C_ClassTalents.LoadConfig, configID, true)
  if not ok then
    return FinishImport(true, "Saved \"" .. label .. "\", but switching to it errored (" .. tostring(result) .. "). Pick it from the loadout dropdown.")
  end
  local R = Enum.LoadConfigResult or {}
  local function WaitForCommit()
    importState.stage = "loading"
    importState.loadingID = configID
    importState.name = label
    importEvents:RegisterEvent("TRAIT_CONFIG_UPDATED")
    importEvents:RegisterEvent("CONFIG_COMMIT_FAILED")
    ImportTimeout(importState.token, "loading", 10, "Saved \"" .. label .. "\" but the switch didn't complete. Pick it from the loadout dropdown in your Talents panel.")
  end
  if result == R.NoChangesNecessary then
    return FinishImport(true, "Applied \"" .. label .. "\".")
  elseif result == R.Ready then
    -- "Ready" means the loadout is staged on the active config, not committed yet.
    if C_Traits.ConfigHasStagedChanges and C_Traits.ConfigHasStagedChanges(importState.configID) and C_ClassTalents.CommitConfig then
      pcall(C_ClassTalents.CommitConfig, importState.configID)
      return WaitForCommit()
    end
    return FinishImport(true, "Applied \"" .. label .. "\". Your action bars may have empty slots for abilities that changed — drag them back from the spellbook.")
  elseif result == R.LoadInProgress then
    return WaitForCommit()
  else
    return FinishImport(true, "Saved \"" .. label .. "\" but the game refused to switch loadouts right now (in an active key or encounter?). Pick it from the loadout dropdown later.")
  end
end

-- Step 2: create the new loadout.
local function CreateLoadout()
  local st = importState
  if C_ClassTalents.CanCreateNewConfig and not C_ClassTalents.CanCreateNewConfig() then
    return FinishImport(false, "No free loadout slot for this spec. Delete one in your Talents panel (or use /hbt clean) and try again.")
  end
  importEvents:RegisterEvent("TRAIT_CONFIG_CREATED")
  st.stage = "creating"
  local ok, success, importError = pcall(C_ClassTalents.ImportLoadout, st.configID, st.entries, st.name, st.importString)
  if not ok then
    return FinishImport(false, "Import call errored (" .. tostring(success) .. "). Use Copy and paste into Talents > Import instead.")
  end
  if not success then
    return FinishImport(false, "Import rejected (" .. tostring(importError) .. "). Use Copy and paste into Talents > Import instead.")
  end
  -- ImportLoadout stages the new loadout; the server creates the config (and fires
  -- TRAIT_CONFIG_CREATED) once it is committed. Commit right away — a no-op when the
  -- client already did it — and retry once in case the first call raced the staging.
  if C_ClassTalents.CommitConfig then
    pcall(C_ClassTalents.CommitConfig, st.configID)
    C_Timer.After(2, function()
      if importState and importState.token == st.token and importState.stage == "creating" then
        pcall(C_ClassTalents.CommitConfig, st.configID)
      end
    end)
  end
  ImportTimeout(st.token, "creating", 12, "The loadout was staged but never confirmed. Open your Talents panel: if it shows pending changes, click Apply Changes.")
end

importEvents:SetScript("OnEvent", function(_, event, arg1)
  local st = importState
  if not st then return end
  if event == "TRAIT_CONFIG_DELETED" and st.stage == "deleting" then
    importEvents:UnregisterEvent("TRAIT_CONFIG_DELETED")
    CreateLoadout()
  elseif event == "TRAIT_CONFIG_CREATED" and st.stage == "creating" then
    local info = type(arg1) == "table" and arg1 or (arg1 and C_Traits.GetConfigInfo(arg1))
    if info and (not Enum.TraitConfigType or info.type == Enum.TraitConfigType.Combat) then
      importEvents:UnregisterEvent("TRAIT_CONFIG_CREATED")
      local label = st.name
      if info.name and info.name ~= st.name and C_ClassTalents.RenameConfig then
        pcall(C_ClassTalents.RenameConfig, info.ID, st.name)
      end
      local dropNote = (st.dropped and st.dropped > 0)
        and (" " .. st.dropped .. " outdated talent" .. (st.dropped == 1 and "" or "s") .. " skipped — check the tree.")
        or ""
      if dropNote ~= "" then Note(dropNote) end
      SwitchToLoadout(info.ID, label)
    end
  elseif event == "TRAIT_CONFIG_UPDATED" and st.stage == "loading" then
    -- Only the ACTIVE config's update means the switch landed; the new loadout's own
    -- update (from the rename above) fires earlier and must not end the flow.
    if arg1 == st.configID then
      FinishImport(true, "Applied \"" .. st.name .. "\". Your action bars may have empty slots for abilities that changed — drag them back from the spellbook.")
    end
  elseif event == "CONFIG_COMMIT_FAILED" and st.stage == "loading" then
    FinishImport(false, "Saved \"" .. st.name .. "\" but applying it failed (in combat, or talents are locked in this instance?). Pick it from the loadout dropdown later.")
  end
end)

-- Entry point from a card's Import button.
function HBT.ImportBuild(bossName, variant)
  if importState then
    return Fail("An import is already in progress — give it a second.")
  end
  if not variant or (not ParseEntries(variant) and not variant.importString) then
    return Fail("No import data for this build.")
  end
  if not (C_ClassTalents and C_ClassTalents.ImportLoadout) then
    return Fail("Talent import API not found on this client. Use Copy and paste into Talents > Import instead.")
  end
  if InCombatLockdown() then
    return Fail("Can't import talents in combat.")
  end
  if PlayerSpellsFrame and PlayerSpellsFrame.IsInspecting and PlayerSpellsFrame:IsInspecting() then
    return Fail("Close the inspect view first.")
  end
  if C_ClassTalents.GetStarterBuildActive and C_ClassTalents.GetStarterBuildActive() then
    return Fail("Starter Build is active. Turn it off in your Talents panel first, then import.")
  end
  local configID, treeID = GetActiveConfig()
  if not configID then
    return Fail("Could not find your active talent config. Open your Talents panel (N) once, then try again.")
  end
  if C_Traits.ConfigHasStagedChanges and C_Traits.ConfigHasStagedChanges(configID) then
    return Fail("You have unsaved talent changes. Apply or discard them in your Talents panel first.")
  end

  local specID = GetCurrentSpecID()
  local entries, dropped, err = EntriesForVariant(variant, configID, treeID)
  if not entries then
    return Fail("This build's recorded talents no longer match the current game version (" .. tostring(err) .. "). It should fix itself after the next data update.")
  end

  local name = LoadoutNameFor(bossName, variant)
  local target = StateFromEntries(entries, configID)

  -- Already running this exact build? Nothing to create.
  local current = GetCurrentState(configID, treeID)
  if current and DiffStates(current, target).total == 0 then
    return Note("Your current talents already match this build.")
  end

  importState = {
    token = {}, name = name, specID = specID, configID = configID, treeID = treeID,
    entries = entries, dropped = dropped, importString = StringForVariant(variant),
  }

  -- Prefer switching to a saved loadout that already equals the build (keeps that
  -- loadout's own action-bar layout), then replace an older HBT loadout of this name.
  local toDelete
  for _, cfg in ipairs(SavedConfigsForSpec(specID)) do
    if cfg.ID ~= configID then
      local same = false
      if C_Traits.GenerateImportString then
        local okStr, str = pcall(C_Traits.GenerateImportString, cfg.ID)
        if okStr and type(str) == "string" and str ~= "" then
          local saved = DecodeLoadoutString(str, configID, treeID, true)
          if saved then same = DiffStates(StateFromEntries(saved, configID), target).total == 0 end
        end
      end
      if same then
        Note("Your saved loadout \"" .. cfg.name .. "\" already matches — switching to it.")
        return SwitchToLoadout(cfg.ID, cfg.name)
      end
      if db.replaceExisting and cfg.name == name then toDelete = cfg.ID end
    end
  end

  if toDelete and C_ClassTalents.DeleteConfig then
    importState.stage = "deleting"
    importEvents:RegisterEvent("TRAIT_CONFIG_DELETED")
    local ok, deleted = pcall(C_ClassTalents.DeleteConfig, toDelete)
    if ok and deleted ~= false then
      ImportTimeout(importState.token, "deleting", 5, "Couldn't replace the old \"" .. name .. "\" loadout. Delete it in your Talents panel and try again.")
      return
    end
    importEvents:UnregisterEvent("TRAIT_CONFIG_DELETED")
  end
  CreateLoadout()
end

-- Deletes every HBT-created loadout for the current spec (confirmation popup in the slash handler).
function HBT.CleanLoadouts()
  if InCombatLockdown() then return Fail("Can't change loadouts in combat.") end
  local specID = GetCurrentSpecID()
  if not specID or not C_ClassTalents.DeleteConfig then return end
  local n = 0
  for _, cfg in ipairs(SavedConfigsForSpec(specID)) do
    if cfg.name:sub(1, #LOADOUT_PREFIX) == LOADOUT_PREFIX then
      if pcall(C_ClassTalents.DeleteConfig, cfg.ID) then n = n + 1 end
    end
  end
  Note("Removed " .. n .. " HotsBB loadout" .. (n == 1 and "" or "s") .. " for this spec.")
end

-- ── Design system ────────────────────────────────────────────────────────────
-- Drawn from plain colour textures and font strings: no Blizzard frame templates, no
-- shipped art, nothing that can break when an atlas name changes.

local COLOR_BG           = { 0.045, 0.045, 0.055 }
local COLOR_TITLEBAR     = { 0.02, 0.02, 0.03 }
local COLOR_PANEL        = { 0.10, 0.10, 0.12 }
local COLOR_PANEL_HOVER  = { 0.13, 0.13, 0.16 }
local COLOR_TEXT         = { 0.94, 0.94, 0.96 }
local COLOR_TEXT_MUTED   = { 0.52, 0.52, 0.57 }
local COLOR_BTN          = { 0.15, 0.15, 0.18 }
local COLOR_BTN_HOVER    = { 0.20, 0.20, 0.24 }
local COLOR_GOLD         = { 1, 0.82, 0 }
local COLOR_GREEN        = { 0.35, 0.9, 0.45 }
local COLOR_ORANGE       = { 1, 0.6, 0.2 }
local COLOR_RED          = { 1, 0.35, 0.35 }

local COLOR_ACCENT = { 0.55, 0.55, 0.62 }
do
  local _, classToken = UnitClass("player")
  if RAID_CLASS_COLORS and classToken and RAID_CLASS_COLORS[classToken] then
    local c = RAID_CLASS_COLORS[classToken]
    COLOR_ACCENT = { c.r, c.g, c.b }
  end
end

local function Paint(tex, color, alpha)
  tex:SetColorTexture(color[1], color[2], color[3], alpha == nil and 1 or alpha)
end

local function Crisp(tex)
  if tex.SetSnapToPixelGrid then tex:SetSnapToPixelGrid(false) end
  if tex.SetTexelSnappingBias then tex:SetTexelSnappingBias(0) end
end

local function CreatePanel(parent, name)
  local f = CreateFrame("Frame", name, parent)
  f.bg = f:CreateTexture(nil, "BACKGROUND")
  f.bg:SetAllPoints()
  return f
end

-- 1px hairline border from four strips (crisp at any UI scale).
local function AddBorder(frame, color, alpha)
  local edges = {}
  for i, def in ipairs({ { "TOPLEFT", "TOPRIGHT", 1 }, { "BOTTOMLEFT", "BOTTOMRIGHT", 1 }, { "TOPLEFT", "BOTTOMLEFT", 2 }, { "TOPRIGHT", "BOTTOMRIGHT", 2 } }) do
    local t = frame:CreateTexture(nil, "BORDER")
    Paint(t, color or COLOR_TEXT, alpha or 0.08)
    Crisp(t)
    t:SetPoint(def[1])
    t:SetPoint(def[2])
    if def[3] == 1 then t:SetHeight(1) else t:SetWidth(1) end
    edges[i] = t
  end
  frame.borderEdges = edges
  return edges
end

local function SetBorderColor(frame, color, alpha)
  if not frame.borderEdges then return end
  for _, t in ipairs(frame.borderEdges) do Paint(t, color, alpha) end
end

local function CreateDivider(parent, alpha)
  local tex = parent:CreateTexture(nil, "ARTWORK")
  Paint(tex, COLOR_TEXT, alpha or 0.08)
  Crisp(tex)
  return tex
end

-- variant: "primary" (accent fill, dark text), "flat" (subtle fill), "ghost" (text only)
local function CreateFlatButton(parent, text, variant, w, h)
  local btn = CreateFrame("Button", nil, parent)
  btn:SetSize(w or 60, h or 24)
  btn.bg = btn:CreateTexture(nil, "BACKGROUND")
  btn.bg:SetAllPoints()
  btn.variant = variant

  btn.label = btn:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
  btn.label:SetPoint("CENTER")
  btn.label:SetText(text)
  btn:SetFontString(btn.label)

  -- Engine-driven hover: a HIGHLIGHT-layer texture shows only while the cursor is over
  -- the button — no OnEnter/OnLeave bookkeeping to get out of sync with Enable/Disable.
  btn.hl = btn:CreateTexture(nil, "HIGHLIGHT")
  btn.hl:SetAllPoints()
  Paint(btn.hl, COLOR_TEXT, variant == "primary" and 0.12 or 0.07)

  function btn:ApplyIdle()
    if self.variant == "primary" then
      Paint(self.bg, COLOR_ACCENT, 0.9)
      self.label:SetTextColor(0.05, 0.05, 0.05)
    elseif self.variant == "ghost" then
      Paint(self.bg, COLOR_TEXT, 0)
      self.label:SetTextColor(COLOR_TEXT_MUTED[1], COLOR_TEXT_MUTED[2], COLOR_TEXT_MUTED[3])
    else
      Paint(self.bg, COLOR_BTN)
      self.label:SetTextColor(COLOR_TEXT[1], COLOR_TEXT[2], COLOR_TEXT[3])
    end
    if not self:IsEnabled() then self:SetAlpha(0.4) else self:SetAlpha(1) end
  end
  btn:ApplyIdle()
  btn:HookScript("OnEnable", btn.ApplyIdle)
  btn:HookScript("OnDisable", btn.ApplyIdle)
  return btn
end

-- Toggle button for tabs/pills: persistent selected state (accent underline).
local function CreateToggleButton(parent, text, w, h)
  local btn = CreateFrame("Button", nil, parent)
  btn:SetSize(w or 80, h or 24)
  btn.bg = btn:CreateTexture(nil, "BACKGROUND")
  btn.bg:SetAllPoints()
  Paint(btn.bg, COLOR_TEXT, 0)
  btn.hl = btn:CreateTexture(nil, "HIGHLIGHT")
  btn.hl:SetAllPoints()
  Paint(btn.hl, COLOR_TEXT, 0.05)

  btn.underline = btn:CreateTexture(nil, "ARTWORK")
  btn.underline:SetPoint("BOTTOMLEFT", 0, 0)
  btn.underline:SetPoint("BOTTOMRIGHT", 0, 0)
  btn.underline:SetHeight(2)
  Crisp(btn.underline)
  Paint(btn.underline, COLOR_ACCENT, 0)

  btn.icon = btn:CreateTexture(nil, "ARTWORK")
  btn.icon:SetSize(14, 14)
  btn.icon:SetPoint("LEFT", 8, 0)
  btn.icon:Hide()

  btn.label = btn:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
  btn.label:SetPoint("CENTER")
  btn.label:SetText(text)
  btn.label:SetTextColor(COLOR_TEXT_MUTED[1], COLOR_TEXT_MUTED[2], COLOR_TEXT_MUTED[3])

  function btn:SetSelected(selected)
    self.selected = selected
    if selected then
      Paint(self.underline, COLOR_ACCENT, 1)
      self.label:SetTextColor(COLOR_TEXT[1], COLOR_TEXT[2], COLOR_TEXT[3])
    else
      Paint(self.underline, COLOR_ACCENT, 0)
      self.label:SetTextColor(COLOR_TEXT_MUTED[1], COLOR_TEXT_MUTED[2], COLOR_TEXT_MUTED[3])
    end
  end
  return btn
end

local function SetTooltip(frame, titleFn)
  frame:HookScript("OnEnter", function(self)
    local title, lines = titleFn(self)
    if not title then return end
    GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
    GameTooltip:SetText(title, 1, 1, 1)
    if lines then
      for _, line in ipairs(lines) do
        if type(line) == "table" then
          GameTooltip:AddLine(line[1], line[2], line[3], line[4], true)
        else
          GameTooltip:AddLine(line, COLOR_TEXT_MUTED[1], COLOR_TEXT_MUTED[2], COLOR_TEXT_MUTED[3], true)
        end
      end
    end
    GameTooltip:Show()
  end)
  frame:HookScript("OnLeave", function() GameTooltip:Hide() end)
end

-- ── Copy popup & chat link ───────────────────────────────────────────────────

StaticPopupDialogs["HOTSBB_TALENTS_CLEAN"] = {
  text = "Delete every \"" .. LOADOUT_PREFIX .. "…\" talent loadout for your current spec?",
  button1 = YES or "Yes", button2 = NO or "No",
  OnAccept = function() HBT.CleanLoadouts() end,
  timeout = 0, whileDead = true, hideOnEscape = true, preferredIndex = 3,
}

-- Copy box: the addon's own small panel rather than a shared StaticPopup, so it can
-- watch for Ctrl+C and close itself the moment the string is copied. (Addons cannot
-- read the clipboard; the key chord is the signal that the copy happened.)
local copyFrame = CreatePanel(UIParent, "HotsBBTalentsCopyFrame")
copyFrame:SetSize(460, 118)
copyFrame:SetPoint("CENTER", 0, 120)
copyFrame:SetFrameStrata("DIALOG")
copyFrame:SetMovable(true)
copyFrame:EnableMouse(true)
copyFrame:SetClampedToScreen(true)
copyFrame:RegisterForDrag("LeftButton")
copyFrame:SetScript("OnDragStart", copyFrame.StartMoving)
copyFrame:SetScript("OnDragStop", copyFrame.StopMovingOrSizing)
copyFrame:Hide()
Paint(copyFrame.bg, COLOR_BG, 0.98)
AddBorder(copyFrame, COLOR_TEXT, 0.12)
tinsert(UISpecialFrames, "HotsBBTalentsCopyFrame")

local copyStrip = copyFrame:CreateTexture(nil, "ARTWORK")
copyStrip:SetPoint("TOPLEFT"); copyStrip:SetPoint("TOPRIGHT"); copyStrip:SetHeight(3)
Paint(copyStrip, COLOR_ACCENT, 0.9)

copyFrame.title = copyFrame:CreateFontString(nil, "OVERLAY", "GameFontNormal")
copyFrame.title:SetPoint("TOPLEFT", 14, -14)
copyFrame.title:SetText("Copy build string")
copyFrame.title:SetTextColor(COLOR_TEXT[1], COLOR_TEXT[2], COLOR_TEXT[3])

