-- Blizzard's native clickable talent-build link (opens the import preview for anyone
-- who clicks it in chat). Inserted into the open chat box, or opens one.
local function PostChatLink(importString)
  if not (LinkUtil and LinkUtil.FormatLink) then return ShowCopyBox(importString) end
  local specIndex = GetSpecialization and GetSpecialization()
  local specID, specName = GetSpecializationInfo(specIndex or 1)
  local className, classToken = UnitClass("player")
  local fmt = TALENT_BUILD_CHAT_LINK_TEXT or "%s %s Talents"
  local viewText = "[" .. fmt:format(specName or "", className or "") .. "]"
  local link = LinkUtil.FormatLink("talentbuild", viewText, specID or 0, UnitLevel("player"), importString)
  local color = RAID_CLASS_COLORS and classToken and RAID_CLASS_COLORS[classToken]
  if color and color.WrapTextInColorCode then link = color:WrapTextInColorCode(link) end
  if not ChatEdit_InsertLink(link) then ChatFrame_OpenChat(link) end
end

-- ── Encounter Journal lookups (names, portraits, icons) ──────────────────────
-- Everything here is best-effort and cached; a miss falls back to the English name
-- from the data and a generic icon.

local ejCache = { names = {}, portraits = {}, dungeonIcons = {}, mapIDs = {} }

local function LocalizedName(entry)
  local key = entry.name
  if ejCache.names[key] ~= nil then return ejCache.names[key] or key end
  local name
  if entry.journalId and EJ_GetEncounterInfo then
    local ok, n = pcall(EJ_GetEncounterInfo, entry.journalId)
    if ok and type(n) == "string" and n ~= "" then name = n end
  elseif entry.journalInstanceId and EJ_GetInstanceInfo then
    local ok, n = pcall(EJ_GetInstanceInfo, entry.journalInstanceId)
    if ok and type(n) == "string" and n ~= "" then name = n end
  end
  ejCache.names[key] = name or false
  return name or key
end

-- Instance map ID of a dungeon (for locale-independent "you are here" detection).
local function DungeonMapID(entry)
  if not entry.journalInstanceId or not EJ_GetInstanceInfo then return nil end
  local cached = ejCache.mapIDs[entry.journalInstanceId]
  if cached ~= nil then return cached or nil end
  local ok, _, _, _, _, _, _, _, _, _, mapID = pcall(EJ_GetInstanceInfo, entry.journalInstanceId)
  ejCache.mapIDs[entry.journalInstanceId] = (ok and mapID) or false
  return ok and mapID or nil
end

-- Boss portrait: creature display ID via the journal; applied with Blizzard's own
-- portrait helper. Returns true when something was drawn.
local function SetBossPortrait(tex, entry)
  if not entry.journalId or not EJ_GetCreatureInfo or not SetPortraitTextureFromCreatureDisplayID then return false end
  local displayID = ejCache.portraits[entry.journalId]
  if displayID == nil then
    local ok, _, _, _, d = pcall(EJ_GetCreatureInfo, 1, entry.journalId)
    displayID = (ok and d) or false
    ejCache.portraits[entry.journalId] = displayID
  end
  if not displayID then return false end
  local ok = pcall(SetPortraitTextureFromCreatureDisplayID, tex, displayID)
  return ok
end

-- Dungeon icon: the Mythic+ map icon, matched by instance map ID (locale-independent).
local function SetDungeonIcon(tex, entry)
  local mapID = DungeonMapID(entry)
  if not mapID or not (C_ChallengeMode and C_ChallengeMode.GetMapTable and C_ChallengeMode.GetMapUIInfo) then return false end
  local icon = ejCache.dungeonIcons[mapID]
  if icon == nil then
    icon = false
    local ok, ids = pcall(C_ChallengeMode.GetMapTable)
    if ok and type(ids) == "table" then
      for _, id in ipairs(ids) do
        local ok2, _, _, _, texture, _, instanceMapID = pcall(C_ChallengeMode.GetMapUIInfo, id)
        if ok2 and instanceMapID == mapID and texture then icon = texture; break end
      end
    end
    ejCache.dungeonIcons[mapID] = icon
  end
  if not icon then return false end
  tex:SetTexture(icon)
  tex:SetTexCoord(0.08, 0.92, 0.08, 0.92)
  return true
end

-- Builds a dungeonEncounterID -> journalEncounterID map by scanning the newest journal
-- tier once, for data files without journal IDs. Skipped while the journal is open so its
-- selection isn't disturbed; the tier is restored afterwards.
local journalScan = nil
local function ScanJournalOnce()
  if journalScan ~= nil then return journalScan or nil end
  if not (EJ_GetNumTiers and EJ_SelectTier and EJ_GetInstanceByIndex and EJ_SelectInstance and EJ_GetEncounterInfoByIndex) then
    journalScan = false
    return nil
  end
  if EncounterJournal and EncounterJournal:IsShown() then return nil end
  local map = {}
  local ok = pcall(function()
    local numTiers = EJ_GetNumTiers()
    local savedTier = EJ_GetCurrentTier and EJ_GetCurrentTier()
    for tier = numTiers, math.max(1, numTiers - 1), -1 do
      EJ_SelectTier(tier)
      local i = 1
      while true do
        local instanceID = EJ_GetInstanceByIndex(i, true)
        if not instanceID then break end
        EJ_SelectInstance(instanceID)
        local j = 1
        while true do
          local name, _, journalEncounterID, _, _, _, dungeonEncounterID = EJ_GetEncounterInfoByIndex(j, instanceID)
          if not name then break end
          if dungeonEncounterID and journalEncounterID and not map[dungeonEncounterID] then
            map[dungeonEncounterID] = journalEncounterID
          end
          j = j + 1
        end
        i = i + 1
      end
    end
    if savedTier and savedTier > 0 then EJ_SelectTier(savedTier) end
  end)
  journalScan = ok and map or false
  if ok then
    for _, entry in ipairs(ROSTER.raid) do
      if not entry.journalId and entry.wclId and map[entry.wclId] then entry.journalId = map[entry.wclId] end
    end
  end
  return ok and map or nil
end

