-- ── Tree preview glow ────────────────────────────────────────────────────────
-- Highlights a build's differences on Blizzard's real talent tree by adding one child
-- texture per talent button (never touching Blizzard's own textures or state). Cleared
-- when the panel closes or the player's talents change.

local glowTouched = {}
local previewVariant = nil
local GLOW_ADD, GLOW_REMOVE, GLOW_CHANGE = COLOR_GREEN, COLOR_RED, COLOR_ORANGE

local function ClearTreeGlow()
  for _, btn in ipairs(glowTouched) do
    if btn._hbtGlow then btn._hbtGlow:Hide() end
  end
  wipe(glowTouched)
  previewVariant = nil
end

local function GlowNode(talentsFrame, nodeID, color)
  local ok, btn = pcall(talentsFrame.GetTalentButtonByNodeID, talentsFrame, nodeID)
  if not ok or not btn then return end
  if not btn._hbtGlow then
    local glow = btn:CreateTexture(nil, "OVERLAY", nil, 7)
    if C_Texture and C_Texture.GetAtlasInfo and C_Texture.GetAtlasInfo("bags-glow-orange") then
      glow:SetAtlas("bags-glow-orange")
    else
      glow:SetTexture("Interface\\Buttons\\UI-ActionButton-Border")
      glow:SetBlendMode("ADD")
    end
    local size = math.max(btn:GetWidth() or 0, btn:GetHeight() or 0)
    if size <= 0 then size = 38 end
    glow:SetSize(size + 8, size + 8)
    glow:SetPoint("CENTER", btn, "CENTER")
    btn._hbtGlow = glow
  end
  btn._hbtGlow:SetVertexColor(color[1], color[2], color[3], 0.55)
  btn._hbtGlow:Show()
  glowTouched[#glowTouched + 1] = btn
end

local function TalentsFrameShown()
  local tf = PlayerSpellsFrame and PlayerSpellsFrame.TalentsFrame
  return tf and tf:IsShown() and tf.GetTalentButtonByNodeID and tf or nil
end

local function ApplyTreeGlow(variant)
  ClearTreeGlow()
  local tf = TalentsFrameShown()
  if not tf then return false end
  local diff = DiffVariant(variant)
  if not diff then return false end
  for _, nodeID in ipairs(diff.adds) do GlowNode(tf, nodeID, GLOW_ADD) end
  for _, nodeID in ipairs(diff.removes) do GlowNode(tf, nodeID, GLOW_REMOVE) end
  for _, nodeID in ipairs(diff.changes) do GlowNode(tf, nodeID, GLOW_CHANGE) end
  previewVariant = variant
  return true
end

function HBT.TogglePreview(variant)
  if previewVariant == variant then
    ClearTreeGlow()
    return
  end
  if not TalentsFrameShown() then
    Note("Open your Talents panel (N) and click Preview again — the differences will light up on the tree. Green = take, red = drop, orange = change.")
    previewVariant = variant -- applied as soon as the frame shows
    return
  end
  if ApplyTreeGlow(variant) then
    Note("Preview on your talent tree: green = take, red = drop, orange = change. Click Preview again to clear.")
  end
end

-- ── Cards ────────────────────────────────────────────────────────────────────

local CARD_PAD = 14
local PORTRAIT = 36

local function DescribeDiff(configID, diff)
  local lines = {}
  local function add(list, prefix, color)
    for i, nodeID in ipairs(list) do
      if #lines >= 14 then break end
      lines[#lines + 1] = { prefix .. TalentName(configID, nodeID), color[1], color[2], color[3] }
    end
  end
  add(diff.adds, "+ ", COLOR_GREEN)
  add(diff.changes, "~ ", COLOR_ORANGE)
  add(diff.removes, "− ", COLOR_RED)
  if diff.total > #lines then lines[#lines + 1] = "…and " .. (diff.total - #lines) .. " more" end
  return lines
end

local function RefreshCardButtons(card, variants)
  local variant = variants[card.selectedVariantIndex or 1]
  if not variant then return end
  local label = card.bossName
  if variant.heroTreeName and variant.heroTreeName ~= "Overall" then
    label = label .. " — " .. variant.heroTreeName
  end
  card.variant = variant

  card.importBtn:SetScript("OnClick", function() HBT.ImportBuild(card.bossName, variant) end)
  card.importBtn.label:SetText(db.autoApply and "Import & Apply" or "Import")
  card.importBtn:SetEnabled(not InCombatLockdown())

  local importString = StringForVariant(variant)
  if importString then
    card.copyBtn:SetScript("OnClick", function()
      if IsModifiedClick and IsModifiedClick("CHATLINK") then PostChatLink(importString) else ShowCopyBox(importString) end
    end)
    card.linkBtn:SetScript("OnClick", function() PostChatLink(importString) end)
    card.copyBtn:Show()
    card.linkBtn:Show()
  else
    card.copyBtn:Hide()
    card.linkBtn:Hide()
  end
  card.previewBtn:SetScript("OnClick", function() HBT.TogglePreview(variant) end)

  for i, pill in ipairs(card.pills) do
    if pill:IsShown() then pill:SetSelected(i == (card.selectedVariantIndex or 1)) end
  end

  -- Build-vs-current badge.
  local diff = DiffVariant(variant)
  card.diff = diff
  if not diff then
    card.diffBadge.label:SetText("")
    card.diffBadge:Hide()
  else
    card.diffBadge:Show()
    if diff.total == 0 then
      card.diffBadge.label:SetText("|TInterface\\RaidFrame\\ReadyCheck-Ready:12:12:0:0|t Active build")
      card.diffBadge.label:SetTextColor(COLOR_GREEN[1], COLOR_GREEN[2], COLOR_GREEN[3])
      card.importBtn:SetEnabled(false)
    else
      card.diffBadge.label:SetText(diff.total .. " talent" .. (diff.total == 1 and "" or "s") .. " differ")
      -- Tinted by distance so the list scans at a glance: a few swaps (green), a
      -- noticeable rework (amber), a different build entirely (red).
      local tint = (diff.total <= 3 and COLOR_GREEN) or (diff.total <= 12 and COLOR_ORANGE) or COLOR_RED
      card.diffBadge.label:SetTextColor(tint[1], tint[2], tint[3])
    end
    card.diffBadge:SetWidth(math.max(60, (card.diffBadge.label:GetStringWidth() or 60) + 8))
  end
end

local cardPool = {}
local function GetCard(index)
  local card = cardPool[index]
  if card then return card end
  card = CreatePanel(content)
  card:SetSize(400, 40)
  Paint(card.bg, COLOR_PANEL)
  AddBorder(card, COLOR_TEXT, 0.06)
  card:EnableMouse(true)
  card:SetScript("OnEnter", function(self) if not self.highlighted then Paint(self.bg, COLOR_PANEL_HOVER) end end)
  card:SetScript("OnLeave", function(self) if not self.highlighted then Paint(self.bg, COLOR_PANEL) end end)

  card.accentBar = card:CreateTexture(nil, "ARTWORK")
  card.accentBar:SetPoint("TOPLEFT")
  card.accentBar:SetPoint("BOTTOMLEFT")
  card.accentBar:SetWidth(3)
  Crisp(card.accentBar)
  Paint(card.accentBar, COLOR_GOLD, 0)

  -- "You are here" pulse: an ADD-blended ring that breathes via an alpha animation.
  card.pulse = card:CreateTexture(nil, "BACKGROUND", nil, 1)
  card.pulse:SetAllPoints()
  Paint(card.pulse, COLOR_GOLD, 0.08)
  card.pulse:SetBlendMode("ADD")
  card.pulse:Hide()
  card.pulseAnim = card.pulse:CreateAnimationGroup()
  card.pulseAnim:SetLooping("BOUNCE")
  local a = card.pulseAnim:CreateAnimation("Alpha")
  a:SetFromAlpha(0.35); a:SetToAlpha(1); a:SetDuration(0.9); a:SetSmoothing("IN_OUT")

  -- Circular portrait with a thin ring.
  card.portrait = card:CreateTexture(nil, "ARTWORK")
  card.portrait:SetSize(PORTRAIT, PORTRAIT)
  card.portrait:SetPoint("TOPLEFT", CARD_PAD, -12)
  if card.CreateMaskTexture then
    local mask = card:CreateMaskTexture()
    mask:SetAllPoints(card.portrait)
    mask:SetTexture("Interface\\CHARACTERFRAME\\TempPortraitAlphaMask", "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
    card.portrait:AddMaskTexture(mask)
  end
  card.ring = card:CreateTexture(nil, "OVERLAY")
  card.ring:SetPoint("CENTER", card.portrait, "CENTER")
  card.ring:SetSize(PORTRAIT * 1.42, PORTRAIT * 1.42)
  if C_Texture and C_Texture.GetAtlasInfo and C_Texture.GetAtlasInfo("Artifacts-PerkRing-Final") then
    card.ring:SetAtlas("Artifacts-PerkRing-Final")
  else
    card.ring:Hide()
  end

  card.badge = card:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
  card.badge:SetPoint("TOPRIGHT", -12, -12)
  card.badge:SetJustifyH("RIGHT")
  card.badge:SetTextColor(COLOR_TEXT_MUTED[1], COLOR_TEXT_MUTED[2], COLOR_TEXT_MUTED[3])

  -- Title and sub-line are clipped at the badge column so long localized names never
  -- draw under the sample/diff badges.
  card.header = card:CreateFontString(nil, "OVERLAY", "GameFontNormal")
  card.header:SetPoint("TOPLEFT", card.portrait, "TOPRIGHT", 12, -2)
  card.header:SetPoint("RIGHT", card, "RIGHT", -130, 0)
  card.header:SetJustifyH("LEFT")
  card.header:SetWordWrap(false)
  card.header:SetTextColor(COLOR_TEXT[1], COLOR_TEXT[2], COLOR_TEXT[3])

  card.sub = card:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
  card.sub:SetPoint("TOPLEFT", card.header, "BOTTOMLEFT", 0, -3)
  card.sub:SetPoint("RIGHT", card, "RIGHT", -130, 0)
  card.sub:SetJustifyH("LEFT")
  card.sub:SetWordWrap(false)
  card.sub:SetTextColor(COLOR_TEXT_MUTED[1], COLOR_TEXT_MUTED[2], COLOR_TEXT_MUTED[3])

  card.diffBadge = CreateFrame("Button", nil, card)
  card.diffBadge:SetSize(100, 16)
  card.diffBadge:SetPoint("TOPRIGHT", card.badge, "BOTTOMRIGHT", 0, -3)
  card.diffBadge.label = card.diffBadge:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
  card.diffBadge.label:SetPoint("RIGHT")
  card.diffBadge.label:SetJustifyH("RIGHT")
  card.diffBadge:SetScript("OnClick", function() if card.variant then HBT.TogglePreview(card.variant) end end)
  SetTooltip(card.diffBadge, function()
    local configID = GetActiveConfig()
    if not card.diff or not configID then return nil end
    if card.diff.total == 0 then
      return "Your active talents match this build", { "Nothing to import." }
    end
    local lines = DescribeDiff(configID, card.diff)
    lines[#lines + 1] = " "
    lines[#lines + 1] = { "Click to highlight these on your talent tree.", 1, 0.82, 0 }
    return "Compared with your active talents", lines
  end)

  card.pills = {}
  for i = 1, 4 do
    local pill = CreateToggleButton(card, "", 90, 20)
    card.pills[i] = pill
    SetTooltip(pill, function(self)
      local v = self.variant
      if not v then return nil end
      local lines = { (v.sampleSize or 0) .. " parses ran this hero tree" }
      if v.heroTreeName == "Overall" then lines = { "The blended consensus across every hero tree." } end
      return v.heroTreeName or "Overall", lines
    end)
  end

  card.importBtn = CreateFlatButton(card, "Import", "primary", 104, 22)
  card.copyBtn = CreateFlatButton(card, "Copy", "flat", 54, 22)
  card.linkBtn = CreateFlatButton(card, "Link", "ghost", 44, 22)
  card.previewBtn = CreateFlatButton(card, "Preview", "ghost", 58, 22)
  SetTooltip(card.importBtn, function()
    return db.autoApply and "Import & Apply" or "Import",
      { "Creates a loadout named \"" .. LOADOUT_PREFIX .. "<boss>\"" .. (db.autoApply and " and switches to it." or " (select it in the loadout dropdown to apply).") }
  end)
  SetTooltip(card.copyBtn, function() return "Copy the talent string", { "Paste it into Talents > Import.", "Shift-click to put it in chat as a link." } end)
  SetTooltip(card.linkBtn, function() return "Post as a chat link", { "A clickable talent-build link for your group or guild." } end)
  SetTooltip(card.previewBtn, function() return "Preview on your talent tree", { "Lights up the talents this build would take (green), drop (red) or change (orange) on the real tree. Open your Talents panel first." } end)

  cardPool[index] = card
  return card
end

-- Default pill: the player's saved choice for this encounter, else the variant matching
-- the active hero tree, else the first real hero tree (not the blended Overall).
local function DefaultVariantIndex(entry, variants)
  local saved = charDB.pills[entry.name]
  if saved == false then
    return 1 -- the player explicitly chose the blended "Overall" pill
  elseif saved then
    for i, v in ipairs(variants) do if v.heroTreeId == saved then return i end end
  end
  local active = C_ClassTalents and C_ClassTalents.GetActiveHeroTalentSpec and C_ClassTalents.GetActiveHeroTalentSpec()
  if active then
    for i, v in ipairs(variants) do if v.heroTreeId == active then return i end end
  end
  return #variants > 1 and 2 or 1
end

local function HeroTreeAtlas(heroTreeId)
  local configID = GetActiveConfig()
  if not (configID and heroTreeId and C_Traits.GetSubTreeInfo) then return nil end
  local ok, info = pcall(C_Traits.GetSubTreeInfo, configID, heroTreeId)
  if ok and info and info.iconElementID then return info.iconElementID end
  return nil
end

-- Populates a pooled card; returns its height.
local function PopulateCard(card, entry, encounterData)
  local variants = encounterData and encounterData.variants
  card.entry = entry
  card.bossName = entry.name
  card.header:SetText(LocalizedName(entry))
  card.highlighted = false
  card.pulse:Hide(); card.pulseAnim:Stop()
  Paint(card.accentBar, COLOR_GOLD, 0)
  Paint(card.bg, COLOR_PANEL)
  for _, pill in ipairs(card.pills) do pill:Hide() end

  -- Portrait / icon.
  card.portrait:SetTexCoord(0, 1, 0, 1)
  card.portrait:SetDesaturated(false)
  local drew = false
  if entry.journalId then drew = SetBossPortrait(card.portrait, entry) end
  if not drew and entry.journalInstanceId then drew = SetDungeonIcon(card.portrait, entry) end
  if not drew then
    card.portrait:SetTexture("Interface\\Icons\\INV_Misc_Book_09")
    card.portrait:SetTexCoord(0.08, 0.92, 0.08, 0.92)
  end

  if not variants or #variants == 0 then
    card.badge:SetText("No data yet")
    card.sub:SetText("Not enough top parses this week")
    card.diffBadge:Hide()
    card.importBtn:Hide(); card.copyBtn:Hide(); card.linkBtn:Hide(); card.previewBtn:Hide()
    card.portrait:SetDesaturated(true)
    card:SetHeight(62)
    return 62
  end

  -- Builds that fell back to Heroic (Mythic parses too thin for this boss yet) are
  -- labelled so a Mythic raider knows what they're looking at; the weekly crawl swaps in
  -- the Mythic build on its own once it exists.
  local badge = (encounterData.sampleSize or variants[1].sampleSize or 0) .. " top parses"
  local fellBack = encounterData.difficulty and META and META.raidDifficulty and encounterData.difficulty ~= META.raidDifficulty
  if fellBack then
    local label = (encounterData.difficulty == 4 and "Heroic") or (encounterData.difficulty == 5 and "Mythic") or ("difficulty " .. encounterData.difficulty)
    badge = badge .. " · |cffffa040" .. label .. "|r"
  end
  card.badge:SetText(badge)
  if encounterData.fetchedAt then
    local days = math.floor(((GetServerTime and GetServerTime() or time()) - encounterData.fetchedAt / 1000) / 86400)
    card.sub:SetText((entry.zone and (entry.zone .. " · ") or "") .. "Parses from " .. (days <= 0 and "today" or (days .. "d ago"))
      .. (fellBack and " · not enough Mythic kills yet, showing the Heroic build" or ""))
  else
    card.sub:SetText(entry.zone or "")
  end

  local selectedIndex = card.selectedVariantIndex
  if not selectedIndex or card.selectedFor ~= entry.name or selectedIndex > #variants then
    selectedIndex = DefaultVariantIndex(entry, variants)
  end
  card.selectedVariantIndex = selectedIndex
  card.selectedFor = entry.name

  local hasPills = #variants > 1
  local buttonRowY = -58

  if hasPills then
    local x = CARD_PAD
    local categorizedTotal = 0
    for j = 2, #variants do categorizedTotal = categorizedTotal + (variants[j].sampleSize or 0) end
    for i, variant in ipairs(variants) do
      local pill = card.pills[i]
      if pill then
        pill.variant = variant
        pill:ClearAllPoints()
        pill:SetPoint("TOPLEFT", x, -60)
        local label = variant.heroTreeName or "Overall"
        if variant.heroTreeName and variant.heroTreeName ~= "Overall" and categorizedTotal > 0 then
          local pct = math.floor(((variant.sampleSize or 0) / categorizedTotal) * 100 + 0.5)
          label = label .. "  " .. pct .. "%"
        end
        pill.label:SetText(label)
        local atlas = variant.heroTreeId and HeroTreeAtlas(variant.heroTreeId)
        local textWidth = pill.label:GetStringWidth() or 40
        if atlas then
          pill.icon:SetAtlas(atlas)
          pill.icon:Show()
          pill.label:ClearAllPoints()
          pill.label:SetPoint("LEFT", pill.icon, "RIGHT", 4, 0)
          pill:SetWidth(math.max(64, textWidth + 34))
        else
          pill.icon:Hide()
          pill.label:ClearAllPoints()
          pill.label:SetPoint("CENTER")
          pill:SetWidth(math.max(64, textWidth + 24))
        end
        pill:SetScript("OnClick", function()
          card.selectedVariantIndex = i
          charDB.pills[entry.name] = variant.heroTreeId or false
          RefreshCardButtons(card, variants)
        end)
        pill:Show()
        x = x + pill:GetWidth() + 6
      end
    end
    buttonRowY = -86
  end

  card.importBtn:ClearAllPoints()
  card.importBtn:SetPoint("TOPRIGHT", -12, buttonRowY)
  card.copyBtn:ClearAllPoints()
  card.copyBtn:SetPoint("RIGHT", card.importBtn, "LEFT", -6, 0)
  card.linkBtn:ClearAllPoints()
  card.linkBtn:SetPoint("RIGHT", card.copyBtn, "LEFT", -2, 0)
  card.previewBtn:ClearAllPoints()
  card.previewBtn:SetPoint("TOPLEFT", CARD_PAD, buttonRowY)
  card.importBtn:Show(); card.copyBtn:Show(); card.linkBtn:Show(); card.previewBtn:Show()

  RefreshCardButtons(card, variants)

  local totalHeight = hasPills and 116 or 88
  card:SetHeight(totalHeight)
  return totalHeight
end

-- ── Refresh & tabs ───────────────────────────────────────────────────────────

local function HighlightCard(card)
  card.highlighted = true
  Paint(card.accentBar, COLOR_GOLD, 1)
  Paint(card.bg, COLOR_PANEL_HOVER)
  card.pulse:Show()
  card.pulseAnim:Play()
end

function HBT.Refresh()
  local specID = GetCurrentSpecID()
  for _, card in ipairs(cardPool) do card:Hide() end
  if not specID then
    frame.subtitle:SetText("Could not detect your current specialization.")
    return
  end

  local specData = GetSpecData(specID)
  local roster = RosterFor(activeTabKey)
  local haveCount = 0
  for _, entry in ipairs(roster) do
    if specData and specData[entry.name] then haveCount = haveCount + 1 end
  end

  local tabLabel = activeTabKey == "raid" and "Raid" or "Dungeons"
  local diffLabel = ""
  if META then
    if activeTabKey == "raid" and META.raidDifficultyName then diffLabel = META.raidDifficultyName .. " · "
    elseif activeTabKey ~= "raid" then diffLabel = "Mythic+ · " end
  end
  local seasonLabel = META and META.seasonLabel and (META.seasonLabel .. " · ") or ""
  local warn = ""
  if ROSTER.legacy then warn = "  |cffff6666Data file predates this version — update the addon.|r" end
  if not SCHEMA_OK then warn = "  |cffff6666Data file is newer than this Core.lua — update the addon.|r" end
  frame.subtitle:SetText(seasonLabel .. diffLabel .. tabLabel .. ": " .. haveCount .. " of " .. #roster .. " have builds." .. warn)
  UpdateFreshness()

  content:SetWidth(math.max(1, scrollFrame:GetWidth() or 1))
  local y = 0
  for index, entry in ipairs(roster) do
    local card = GetCard(index)
    card:ClearAllPoints()
    card:SetPoint("TOPLEFT", content, "TOPLEFT", 0, -y)
    card:SetPoint("RIGHT", content, "RIGHT", 0, 0)
    card.topOffset = y
    local h = PopulateCard(card, entry, specData and specData[entry.name])
    card:Show()
    y = y + h + 8
  end
  content:SetHeight(math.max(y, 1))
end

function HBT.RefreshIfShown()
  if frame:IsShown() then HBT.Refresh() end
end

local function SetActiveTab(key)
  activeTabKey = key
  db.lastTab = key
  tabRaidBtn:SetSelected(key == "raid")
  tabDungeonBtn:SetSelected(key == "dungeon")
  HBT.Refresh()
end
tabRaidBtn:SetScript("OnClick", function() SetActiveTab("raid") end)
tabDungeonBtn:SetScript("OnClick", function() SetActiveTab("dungeon") end)

-- Scrolls to and highlights the card for an encounter name (switching tabs as needed).
function HBT.ShowEncounter(tabKey, name)
  if tabKey and tabKey ~= activeTabKey then SetActiveTab(tabKey) end
  for _, card in ipairs(cardPool) do
    if card:IsShown() and card.bossName == name then
      scrollFrame:SetVerticalScroll(math.min(card.topOffset or 0, math.max(0, content:GetHeight() - scrollFrame:GetHeight())))
      HighlightCard(card)
      return true
    end
  end
  return false
end

-- ── Where am I? ──────────────────────────────────────────────────────────────
-- Dungeons: match the current instance map ID against the journal instance (locale-
-- independent), falling back to the English name. Raids: the last boss pulled, via
-- ENCOUNTER_START (its encounterID is the same DungeonEncounter ID WCL uses), so a
-- wipe → /hbt lands on the right card. Cleared when leaving the instance.

local lastEncounterID = nil
local lastEncounterAt = 0

local function DetectCurrentContent()
  local name, instanceType, _, _, _, _, _, instanceMapID = GetInstanceInfo()
  if instanceType == "party" then
    for _, entry in ipairs(ROSTER.dungeons) do
      local mapID = DungeonMapID(entry)
      if (mapID and mapID == instanceMapID) or entry.name == name then return "dungeon", entry.name end
    end
    return "dungeon", nil
  elseif instanceType == "raid" then
    if lastEncounterID then
      for _, entry in ipairs(ROSTER.raid) do
        if entry.wclId == lastEncounterID then return "raid", entry.name end
      end
    end
    return "raid", nil
  end
  return nil, nil
end

frame:SetScript("OnShow", function()
  PlaySound(SOUNDKIT.IG_CHARACTER_INFO_OPEN)
  local tabKey, matchedName = DetectCurrentContent()
  if tabKey then
    activeTabKey = tabKey
  else
    activeTabKey = db.lastTab or "raid"
  end
  tabRaidBtn:SetSelected(activeTabKey == "raid")
  tabDungeonBtn:SetSelected(activeTabKey == "dungeon")
  HBT.InvalidateCurrentState()
  HBT.Refresh()
  if matchedName then HBT.ShowEncounter(nil, matchedName) end
end)
frame:SetScript("OnHide", function()
  PlaySound(SOUNDKIT.IG_CHARACTER_INFO_CLOSE)
  ClearTreeGlow()
end)

-- ── Toggle, slash commands, keybinding, compartment ──────────────────────────

function HBT.Toggle()
  if frame:IsShown() then frame:Hide() else frame:Show() end
end
function HotsBBTalents_Toggle() HBT.Toggle() end
BINDING_HEADER_HOTSBBTALENTS = ADDON_TITLE
BINDING_NAME_HOTSBBTALENTS_TOGGLE = "Toggle " .. ADDON_TITLE

-- AddOn Compartment entry points are wired from the TOC (## AddonCompartmentFunc*).
function HotsBBTalents_OnCompartmentClick(_, buttonName)
  if buttonName == "RightButton" then HBT.OpenSettingsMenu(AddonCompartmentFrame) else HBT.Toggle() end
end
function HotsBBTalents_OnCompartmentEnter(_, button)
  GameTooltip:SetOwner(button or AddonCompartmentFrame, "ANCHOR_LEFT")
  GameTooltip:SetText(ADDON_TITLE, 1, 1, 1)
  GameTooltip:AddLine("Left-click: open  ·  Right-click: settings", COLOR_TEXT_MUTED[1], COLOR_TEXT_MUTED[2], COLOR_TEXT_MUTED[3])
  GameTooltip:Show()
end
function HotsBBTalents_OnCompartmentLeave() GameTooltip:Hide() end

SLASH_HOTSBBTALENTS1 = "/hbt"
SLASH_HOTSBBTALENTS2 = "/hotsbbtalents"
SlashCmdList["HOTSBBTALENTS"] = function(msg)
  msg = strtrim and strtrim(msg or "") or (msg or "")
  local cmd = msg:lower()
  if cmd == "" or cmd == "toggle" then
    -- Deferred a tick: slash dispatch runs inside the chat edit box's script execution,
    -- and a heavy first build there can trip the "script ran too long" watchdog.
    C_Timer.After(0, HBT.Toggle)
  elseif cmd == "config" or cmd == "options" or cmd == "settings" then
    HBT.OpenSettings()
  elseif cmd == "reset" then
    db.panel = {}
    MergeDefaults(db.panel, DEFAULTS.panel)
    db.scale = 1
    RestorePanelGeometry()
    Note("Panel position and size reset.")
  elseif cmd == "clean" then
    StaticPopup_Show("HOTSBB_TALENTS_CLEAN")
  elseif cmd == "raid" or cmd == "dungeons" or cmd == "dungeon" then
    frame:Show()
    SetActiveTab(cmd == "raid" and "raid" or "dungeon")
  elseif cmd == "minimap" then
    db.minimap.hide = not db.minimap.hide
    if HBT.UpdateMinimapButton then HBT.UpdateMinimapButton() end
  else
    print(CHAT_PREFIX .. "commands:")
    print("  /hbt — open or close the panel")
    print("  /hbt raid | dungeons — open on that tab")
    print("  /hbt config — settings")
    print("  /hbt minimap — show/hide the minimap button")
    print("  /hbt clean — delete every \"" .. LOADOUT_PREFIX .. "…\" loadout for this spec")
    print("  /hbt reset — reset panel position and size")
  end
end

-- ── Settings (context menu + Blizzard Settings panel) ────────────────────────

local settingsCategory = nil

function HBT.OpenSettingsMenu(owner)
  if not (MenuUtil and MenuUtil.CreateContextMenu) then return HBT.OpenSettings() end
  MenuUtil.CreateContextMenu(owner or gearBtn, function(_, root)
    root:CreateTitle(ADDON_TITLE)
    local function checkbox(label, key, onChange)
      root:CreateCheckbox(label, function() return db[key] end, function()
        db[key] = not db[key]
        if onChange then onChange() end
        HBT.RefreshIfShown()
      end)
    end
    checkbox("Import also switches to the new loadout", "autoApply")
    checkbox("Replace an older HBT loadout of the same name", "replaceExisting")
    root:CreateDivider()
    checkbox("Button on the Talents screen", "showTalentButton", function() if HBT.UpdateShortcutButtons then HBT.UpdateShortcutButtons() end end)
    checkbox("Button in the Encounter Journal", "showJournalButton", function() if HBT.UpdateShortcutButtons then HBT.UpdateShortcutButtons() end end)
    root:CreateCheckbox("Minimap button", function() return not db.minimap.hide end, function()
      db.minimap.hide = not db.minimap.hide
      if HBT.UpdateMinimapButton then HBT.UpdateMinimapButton() end
    end)
    checkbox("Echo results to chat", "chatMessages")
    root:CreateDivider()
    root:CreateButton("Panel scale: smaller", function() db.scale = math.max(0.7, (db.scale or 1) - 0.1); RestorePanelGeometry() end)
    root:CreateButton("Panel scale: larger", function() db.scale = math.min(1.4, (db.scale or 1) + 0.1); RestorePanelGeometry() end)
    root:CreateButton("Reset panel position", function() SlashCmdList["HOTSBBTALENTS"]("reset") end)
    root:CreateDivider()
    root:CreateButton("Delete my HBT loadouts for this spec…", function() StaticPopup_Show("HOTSBB_TALENTS_CLEAN") end)
    if settingsCategory then
      root:CreateButton("Open in Interface Options", function() HBT.OpenSettings() end)
    end
  end)
end
gearBtn:SetScript("OnClick", function(self) HBT.OpenSettingsMenu(self) end)

function HBT.OpenSettings()
  if settingsCategory and Settings and Settings.OpenToCategory then
    if InCombatLockdown() then return Fail("Settings can't open in combat.") end
    Settings.OpenToCategory(settingsCategory:GetID())
  else
    HBT.OpenSettingsMenu(gearBtn)
  end
end

-- Blizzard Settings integration. The API has shifted across patches, so every call is
-- guarded; the gear menu above is always available regardless.
local function RegisterSettingsPanel()
  if not (Settings and Settings.RegisterVerticalLayoutCategory and Settings.RegisterAddOnSetting and Settings.CreateCheckbox) then return end
  pcall(function()
    local category = Settings.RegisterVerticalLayoutCategory(ADDON_TITLE)
    local function checkbox(key, label, tooltip, onChange)
      local variable = "HotsBBTalents_" .. key
      local setting = Settings.RegisterAddOnSetting(category, variable, key, db, type(DEFAULTS[key]), label, DEFAULTS[key])
      if Settings.SetOnValueChangedCallback then
        Settings.SetOnValueChangedCallback(variable, function()
          if onChange then onChange() end
          HBT.RefreshIfShown()
        end)
      end
      Settings.CreateCheckbox(category, setting, tooltip)
    end
    checkbox("autoApply", "Import also switches to the new loadout", "After creating the loadout, switch to it and apply it. Off: the loadout is only saved; pick it from the Talents dropdown yourself.")
    checkbox("replaceExisting", "Replace an older HBT loadout of the same name", "Keeps one loadout per boss and hero tree instead of piling up copies.")
    checkbox("showTalentButton", "Button on the Talents screen", "A shortcut above the loadout dropdown.", function() if HBT.UpdateShortcutButtons then HBT.UpdateShortcutButtons() end end)
    checkbox("showJournalButton", "Button in the Encounter Journal", "A shortcut on each boss and dungeon page that has a build.", function() if HBT.UpdateShortcutButtons then HBT.UpdateShortcutButtons() end end)
    checkbox("chatMessages", "Echo results to chat", "The on-screen banner always shows; this adds a chat line too.")
    if Settings.CreateSliderOptions and Settings.CreateSlider then
      local setting = Settings.RegisterAddOnSetting(category, "HotsBBTalents_scale", "scale", db, "number", "Panel scale", DEFAULTS.scale)
      local options = Settings.CreateSliderOptions(0.7, 1.4, 0.05)
      if options.SetLabelFormatter and MinimalSliderWithSteppersMixin then
        options:SetLabelFormatter(MinimalSliderWithSteppersMixin.Label.Right, function(v) return string.format("%d%%", v * 100 + 0.5) end)
      end
      if Settings.SetOnValueChangedCallback then
        Settings.SetOnValueChangedCallback("HotsBBTalents_scale", function() RestorePanelGeometry() end)
      end
      Settings.CreateSlider(category, setting, options, "Size of the HotsBB Talents panel.")
    end
    Settings.RegisterAddOnCategory(category)
    settingsCategory = category
  end)
end

-- ── Minimap button (no libraries) ────────────────────────────────────────────

local minimapButton
local function PositionMinimapButton()
  if not minimapButton then return end
  local angle = math.rad(db.minimap.angle or 220)
  local radius = (math.max(Minimap:GetWidth(), Minimap:GetHeight()) / 2) + 5
  minimapButton:ClearAllPoints()
  minimapButton:SetPoint("CENTER", Minimap, "CENTER", math.cos(angle) * radius, math.sin(angle) * radius)
end

local function CreateMinimapButton()
  if minimapButton or not Minimap then return end
  local b = CreateFrame("Button", "HotsBBTalentsMinimapButton", Minimap)
  b:SetSize(32, 32)
  b:SetFrameStrata("MEDIUM")
  b:SetFrameLevel(8)
  b:RegisterForClicks("LeftButtonUp", "RightButtonUp", "MiddleButtonUp")
  b:RegisterForDrag("LeftButton")
  b:SetHighlightTexture("Interface\\Minimap\\UI-Minimap-ZoomButton-Highlight")

  local bg = b:CreateTexture(nil, "BACKGROUND")
  bg:SetSize(22, 22)
  bg:SetPoint("CENTER", 0, 1)
  bg:SetTexture("Interface\\Minimap\\UI-Minimap-Background")
  bg:SetVertexColor(0, 0, 0, 0.8)

  local icon = b:CreateTexture(nil, "ARTWORK")
  icon:SetSize(18, 18)
  icon:SetPoint("CENTER", 0, 1)
  icon:SetTexture("Interface\\Icons\\INV_Misc_Book_09")
  icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)

  local border = b:CreateTexture(nil, "OVERLAY")
  border:SetSize(53, 53)
  border:SetPoint("TOPLEFT")
  border:SetTexture("Interface\\Minimap\\MiniMap-TrackingBorder")

  b:SetScript("OnDragStart", function(self)
    self:SetScript("OnUpdate", function()
      local mx, my = Minimap:GetCenter()
      local cx, cy = GetCursorPosition()
      local scale = Minimap:GetEffectiveScale()
      db.minimap.angle = math.deg(math.atan2(cy / scale - my, cx / scale - mx))
      PositionMinimapButton()
    end)
  end)
  b:SetScript("OnDragStop", function(self) self:SetScript("OnUpdate", nil) end)
  b:SetScript("OnClick", function(self, button)
    if button == "RightButton" then HBT.OpenSettingsMenu(self)
    elseif button == "MiddleButton" then db.minimap.hide = true; HBT.UpdateMinimapButton()
    else HBT.Toggle() end
  end)
  b:SetScript("OnEnter", function(self)
    GameTooltip:SetOwner(self, "ANCHOR_NONE")
    GameTooltip:SetPoint("TOPRIGHT", self, "TOPLEFT", -2, 0)
    GameTooltip:SetText(ADDON_TITLE, 1, 1, 1)
    GameTooltip:AddLine("Left-click: open  ·  Right-click: settings", COLOR_TEXT_MUTED[1], COLOR_TEXT_MUTED[2], COLOR_TEXT_MUTED[3])
    GameTooltip:AddLine("Drag to move  ·  Middle-click to hide", COLOR_TEXT_MUTED[1], COLOR_TEXT_MUTED[2], COLOR_TEXT_MUTED[3])
    GameTooltip:Show()
  end)
  b:SetScript("OnLeave", function() GameTooltip:Hide() end)
  minimapButton = b
  PositionMinimapButton()
end

function HBT.UpdateMinimapButton()
  if db.minimap.hide then
    if minimapButton then minimapButton:Hide() end
  else
    CreateMinimapButton()
    if minimapButton then minimapButton:Show(); PositionMinimapButton() end
  end
end

-- ── Shortcut buttons: Talents screen & Encounter Journal ─────────────────────

local talentButton, journalButton

local function CreateShortcutButton(parent, width)
  local btn = CreateFlatButton(parent, ADDON_TITLE, "flat", width or 160, 20)
  btn:SetFrameStrata("HIGH")
  btn.label:SetFont(select(1, btn.label:GetFont()), 10)
  local accentLine = btn:CreateTexture(nil, "ARTWORK")
  accentLine:SetPoint("BOTTOMLEFT", 2, 1)
  accentLine:SetPoint("BOTTOMRIGHT", -2, 1)
  accentLine:SetHeight(2)
  Crisp(accentLine)
  Paint(accentLine, COLOR_ACCENT, 0.9)
  return btn
end

-- Raider.IO parks its own shortcut directly above the loadout dropdown; when it's
-- loaded ours sits one row higher instead of on top of it.
local function RaiderIOLoaded()
  return C_AddOns and C_AddOns.IsAddOnLoaded and C_AddOns.IsAddOnLoaded("RaiderIO")
end

local function SetupTalentScreenButton()
  if talentButton then return end
  local tf = PlayerSpellsFrame and PlayerSpellsFrame.TalentsFrame
  local dropdown = tf and tf.LoadSystem and tf.LoadSystem.Dropdown
  if not dropdown then
    -- Older frame layout: fall back to the whole talents frame with a fixed offset.
    if not tf then return end
    talentButton = CreateShortcutButton(tf, 200)
    talentButton:SetPoint("BOTTOMLEFT", tf, "BOTTOMLEFT", 15, RaiderIOLoaded() and 119 or 95)
  else
    talentButton = CreateShortcutButton(dropdown, math.max(140, dropdown:GetWidth() or 160))
    talentButton:SetPoint("BOTTOMLEFT", dropdown, "TOPLEFT", 0, RaiderIOLoaded() and 40 or 16)
  end
  talentButton:SetScript("OnClick", HBT.Toggle)
  SetTooltip(talentButton, function() return ADDON_TITLE, { "Meta builds per boss and dungeon for this spec." } end)
  function talentButton:UpdateVisibility()
    local inspecting = tf.IsInspecting and tf:IsInspecting()
    self:SetShown(db.showTalentButton and not inspecting)
  end
  talentButton:UpdateVisibility()
  if tf.HookScript then
    tf:HookScript("OnShow", function()
      talentButton:UpdateVisibility()
      if previewVariant then ApplyTreeGlow(previewVariant) end
    end)
    tf:HookScript("OnHide", function() ClearTreeGlow() end)
  end
end

local function JournalSelection()
  local instanceID = EncounterJournal and EncounterJournal.instanceID
  local encounterID = EncounterJournal and EncounterJournal.encounterID
  if encounterID then
    for _, entry in ipairs(ROSTER.raid) do
      if entry.journalId == encounterID then return "raid", entry end
    end
  end
  if instanceID then
    for _, entry in ipairs(ROSTER.dungeons) do
      if entry.journalInstanceId == instanceID then return "dungeon", entry end
    end
  end
  return nil
end

local function SetupJournalButton()
  if journalButton then return end
  local anchor = EncounterJournalEncounterFrameInfoDifficulty
  if not anchor then return end
  journalButton = CreateShortcutButton(anchor, 140)
  journalButton:SetPoint("BOTTOMLEFT", anchor, "TOPLEFT", 0, RaiderIOLoaded() and 25 or 1)
  journalButton.label:SetText("HotsBB build")
  journalButton:SetScript("OnClick", function()
    local tabKey, entry = JournalSelection()
    if not entry then return end
    frame:Show()
    HBT.ShowEncounter(tabKey, entry.name)
  end)
  SetTooltip(journalButton, function()
    local _, entry = JournalSelection()
    return ADDON_TITLE, { entry and ("Meta build for " .. LocalizedName(entry) .. " for your current spec.") or "" }
  end)
  function journalButton:UpdateVisibility()
    if not db.showJournalButton then return self:Hide() end
    local _, entry = JournalSelection()
    local specData = GetSpecData(GetCurrentSpecID())
    self:SetShown(entry ~= nil and specData ~= nil and specData[entry.name] ~= nil)
  end
  local function update() journalButton:UpdateVisibility() end
  anchor:HookScript("OnShow", update)
  if type(_G.EncounterJournal_DisplayEncounter) == "function" then hooksecurefunc("EncounterJournal_DisplayEncounter", update) end
  if type(_G.EncounterJournal_DisplayInstance) == "function" then hooksecurefunc("EncounterJournal_DisplayInstance", update) end
  update()
end

function HBT.UpdateShortcutButtons()
  if talentButton then talentButton:UpdateVisibility() end
  if journalButton then journalButton:UpdateVisibility() end
end

local function WhenAddOnLoaded(name, fn)
  if EventUtil and EventUtil.ContinueOnAddOnLoaded then
    EventUtil.ContinueOnAddOnLoaded(name, fn)
  elseif C_AddOns and C_AddOns.IsAddOnLoaded and C_AddOns.IsAddOnLoaded(name) then
    fn()
  else
    local w = CreateFrame("Frame")
    w:RegisterEvent("ADDON_LOADED")
    w:SetScript("OnEvent", function(self, _, loaded)
      if loaded == name then self:UnregisterAllEvents(); fn() end
    end)
  end
end

-- ── Events ───────────────────────────────────────────────────────────────────

local events = CreateFrame("Frame")
events:RegisterEvent("ADDON_LOADED")
events:RegisterEvent("PLAYER_LOGIN")
events:RegisterEvent("PLAYER_ENTERING_WORLD")
events:RegisterEvent("ENCOUNTER_START")
events:RegisterEvent("PLAYER_REGEN_DISABLED")
events:RegisterEvent("PLAYER_REGEN_ENABLED")
events:RegisterEvent("TRAIT_CONFIG_UPDATED")
events:RegisterEvent("TRAIT_NODE_CHANGED")
events:RegisterEvent("TRAIT_TREE_CHANGED")
events:RegisterEvent("TRAIT_CONFIG_LIST_UPDATED")
events:RegisterUnitEvent("PLAYER_SPECIALIZATION_CHANGED", "player")

local refreshPending = false
local function DebouncedRefresh()
  if refreshPending then return end
  refreshPending = true
  C_Timer.After(0.25, function()
    refreshPending = false
    HBT.InvalidateCurrentState()
    HBT.RefreshIfShown()
    if previewVariant and TalentsFrameShown() then ApplyTreeGlow(previewVariant) end
  end)
end

events:SetScript("OnEvent", function(_, event, arg1)
  if event == "ADDON_LOADED" then
    if arg1 == ADDON_NAME then
      InitSavedVariables()
      RestorePanelGeometry()
      RegisterSettingsPanel()
    end
  elseif event == "PLAYER_LOGIN" then
    HBT.UpdateMinimapButton()
    WhenAddOnLoaded("Blizzard_PlayerSpells", SetupTalentScreenButton)
    WhenAddOnLoaded("Blizzard_EncounterJournal", SetupJournalButton)
    -- Version notice: once per update, never on a fresh install's first login beyond a
    -- short pointer to the slash command.
    local version = C_AddOns and C_AddOns.GetAddOnMetadata and C_AddOns.GetAddOnMetadata(ADDON_NAME, "Version")
    if version and db.lastSeenVersion ~= version then
      if db.lastSeenVersion then
        print(CHAT_PREFIX .. "updated to v" .. version .. ". Type /hbt to open.")
      else
        print(CHAT_PREFIX .. "loaded. Type /hbt (or use the minimap button) to see meta builds for your spec.")
      end
      db.lastSeenVersion = version
    end
    -- Fill journal IDs the data file lacks, once, a few seconds after login.
    C_Timer.After(5, function()
      local missing = false
      for _, entry in ipairs(ROSTER.raid) do if not entry.journalId then missing = true end end
      if missing then ScanJournalOnce() end
    end)
  elseif event == "PLAYER_ENTERING_WORLD" then
    local _, instanceType = GetInstanceInfo()
    if instanceType ~= "raid" then lastEncounterID = nil end
    DebouncedRefresh()
  elseif event == "ENCOUNTER_START" then
    lastEncounterID, lastEncounterAt = arg1, GetTime()
  elseif event == "PLAYER_REGEN_DISABLED" or event == "PLAYER_REGEN_ENABLED" then
    HBT.RefreshIfShown()
  elseif event == "PLAYER_SPECIALIZATION_CHANGED" then
    UpdateSpecIcon()
    ClearTreeGlow() -- talent buttons are re-pooled on a spec change; stale glows would land on other nodes
    wipe(subTreeNodeCache)
    for _, card in ipairs(cardPool) do card.selectedFor = nil end
    DebouncedRefresh()
    HBT.UpdateShortcutButtons()
  elseif event == "TRAIT_CONFIG_UPDATED" or event == "TRAIT_NODE_CHANGED" or event == "TRAIT_TREE_CHANGED" or event == "TRAIT_CONFIG_LIST_UPDATED" then
    DebouncedRefresh()
  end
end)

